const KB=DATA.kb, M=DATA.manifest, STATS=DATA.stats, GRAPH=DATA.graph, REL=DATA.relations;
const docs=Object.fromEntries(KB.documentos.map(x=>[x.id,x]));
const topics=KB.temas, questions=KB.preguntas_teoricas, exercises=KB.ejercicios, skills=KB.habilidades;
const topicMap=Object.fromEntries(topics.map(x=>[x.id,x]));
const skillMap=Object.fromEntries(skills.map(x=>[x.id,x]));
const palette=['#e85d3f','#2b7a78','#6b5ca5','#c5832b','#2f6f9f','#8a5a44','#4f7c4a','#9b4f73','#5c6670','#b34c3f','#4d7a88','#7a5d9b','#af6f2f','#477a65','#8b6c30','#566b78'];
const topicColor=Object.fromEntries(topics.map((t,i)=>[t.id,palette[i%palette.length]]));
const sourceLabel={nota:'Nota',practico:'Práctico',taller:'Taller',parcial:'Parcial',examen:'Examen',presentacion:'Presentación'};
const STORAGE='arqui_exam_dashboard_v3';
const defaultState={questionResults:{},markedQuestions:[],exerciseStatus:{},reviewExerciseIds:[],workshopStatus:{},skillStatus:{},checklist:{},favorites:[],simulations:[],lastSection:'inicio',lastTopic:null,filters:{},lastQuestion:null,lastExercise:null};
let state=loadState(); let theoryCurrent=null, practiceCurrent=null, bankSelected=null, explorerSelected=null, sourceSelected=null, sim=null;
function loadState(){
  try{
    const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');
    const merged={...structuredClone(defaultState),...saved};
    merged.questionResults=saved.questionResults||{};
    merged.exerciseStatus=saved.exerciseStatus||{};
    merged.reviewExerciseIds=Array.isArray(saved.reviewExerciseIds)?[...new Set(saved.reviewExerciseIds)]:[];
    Object.entries(merged.exerciseStatus).forEach(([id,status])=>{
      if(status==='repasar'&&!merged.reviewExerciseIds.includes(id))merged.reviewExerciseIds.push(id);
    });
    return merged;
  }catch{return structuredClone(defaultState)}
}
function save(){localStorage.setItem(STORAGE,JSON.stringify(state))}
function isExerciseForReview(id){return state.reviewExerciseIds.includes(id)||state.exerciseStatus[id]==='repasar'}
function setExerciseForReview(id,value=true){
  const set=new Set(state.reviewExerciseIds);
  if(value){set.add(id);state.exerciseStatus[id]='repasar'}
  else{set.delete(id);if(state.exerciseStatus[id]==='repasar')delete state.exerciseStatus[id]}
  state.reviewExerciseIds=[...set];
}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(s=''){return esc(s).replace(/\n/g,'<br>')}
function uniq(a){return [...new Set(a.filter(Boolean))]}
function $id(id){return document.getElementById(id)}
function docOf(x){return docs[x.documento||x.fuente]||{}}
function topicName(id){return topicMap[id]?.nombre||id||'Sin tema'}
function sourceType(x){return docOf(x).source_type||x.tipo||docOf(x).tipo||'otro'}
function chip(text,cls=''){return `<span class="chip ${cls}">${esc(text)}</span>`}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function optionList(vals,current='',all='Todos'){return `<option value="">${all}</option>`+vals.map(v=>`<option value="${esc(v.value??v)}" ${(v.value??v)==current?'selected':''}>${esc(v.label??v)}</option>`).join('')}
function yearValues(arr){return uniq(arr.map(x=>x.anio).filter(Boolean)).sort((a,b)=>b-a)}
function getQuestionState(id){const r=state.questionResults[id]; if(!r)return 'no_iniciada'; if((r.correct||0)>(r.wrong||0))return 'dominada'; return 'repasar'}
function getExerciseState(id){return state.exerciseStatus[id]||'no_iniciado'}
function questionFrequency(q){return q.frecuencia||1}
function difficulty(x){let score=(x.texto_completo||x.enunciado_completo||'').length/500+(x.habilidades?.length||0)*.4+(sourceType(x)==='examen'?1:.2);return score>3?'Alta':score>1.4?'Media':'Baja'}
function progress(){
 const qDone=Object.keys(state.questionResults).length, eDone=Object.values(state.exerciseStatus).filter(x=>x==='resuelto').length;
 const wDone=Object.values(state.workshopStatus).filter(x=>x==='resuelto').length, sDone=Object.values(state.skillStatus).filter(x=>x==='dominada').length;
 const pct=Math.round(100*(qDone/questions.length*.35+eDone/exercises.length*.35+wDone/Math.max(1,M.cantidad_talleres)*.15+sDone/skills.length*.15));
 return {pct,qDone,eDone,wDone,sDone};
}
function topicProgress(id){
 const qs=questions.filter(x=>x.tema===id), es=exercises.filter(x=>x.tema===id);
 const qd=qs.filter(x=>state.questionResults[x.id]).length, ed=es.filter(x=>state.exerciseStatus[x.id]==='resuelto').length;
 return Math.round(100*((qs.length?qd/qs.length:0)*.5+(es.length?ed/es.length:0)*.5));
}
function topicPriorities(){
 const max=Math.max(...Object.values(STATS.frecuencia_por_tema||{}),1);
 return topics.map((t,i)=>{const freq=(STATS.frecuencia_por_tema?.[t.id]||0)/max;const pending=1-topicProgress(t.id)/100;const order=(topics.length-i)/topics.length;return {...t,score:Math.round(100*(freq*.58+pending*.32+order*.10))}}).sort((a,b)=>b.score-a.score);
}
function topicStyle(id){return `--topic:${topicColor[id]||'#657180'}`}
function navTo(section,opts={}){
 state.lastSection=section;if(opts.topic)state.lastTopic=opts.topic;save();
 document.body.classList.toggle('roadmap-home-mode',section==='inicio');
 document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));
 document.getElementById('sec-'+section)?.classList.add('active');
 document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.section===section));
 document.getElementById('sidebar').classList.remove('open');
 render(section);window.scrollTo({top:0,behavior:'smooth'});
}
function sectionHeader(kicker,title,text,actions=''){return `<div class="section-head"><div>${kicker?`<div class="eyebrow">${esc(kicker)}</div>`:''}<h1>${esc(title)}</h1>${text?`<p>${esc(text)}</p>`:''}</div>${actions}</div>`}
function render(section){({inicio:renderHome,temas:renderTopics,habilidades:renderSkills,teoria:renderTheory,practica:renderPractice,talleres:renderWorkshops,banco:renderBank,explorador:renderExplorer,checklist:renderChecklist,simulacro:renderSimulation,estadisticas:renderStats,fuentes:renderSources,examenes:renderExamsOverview}[section]||renderHome)()}
function bindNav(){document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>navTo(b.dataset.section,{topic:b.dataset.topic}));document.querySelectorAll('[data-topic-jump]').forEach(b=>b.onclick=()=>{state.lastTopic=b.dataset.topicJump;navTo('temas',{topic:b.dataset.topicJump})})}
function renderSidebar(){
 document.getElementById('sidebarTopics').innerHTML=topics.map(t=>`<button class="topic-jump" data-topic-jump="${t.id}"><span style="width:9px;height:9px;border-radius:50%;background:${topicColor[t.id]};display:inline-block"></span>${esc(t.nombre)}</button>`).join('');bindNav();
}
function renderHome(){
 const p=progress(), pri=topicPriorities().slice(0,5), top=topicPriorities().slice(0,8);
 const html=`<div class="hero"><div class="hero-main"><div class="eyebrow">Mapa personal de estudio</div><h1 class="page-title">Prepará el examen con el material real del curso.</h1><p class="lead">La base reúne enunciados completos, soluciones oficiales identificadas, talleres, notas y relaciones entre temas.</p>
 <div class="metric-grid"><div class="metric"><b>${M.cantidad_temas}</b><span>temas</span></div><div class="metric"><b>${M.cantidad_ejercicios}</b><span>ejercicios</span></div><div class="metric"><b>${M.cantidad_preguntas_teoricas}</b><span>preguntas teóricas</span></div><div class="metric"><b>${p.pct}%</b><span>progreso general</span></div></div>
 <div class="bar"><span style="width:${p.pct}%"></span></div><div class="quick-actions"><button class="btn primary" data-section="${state.lastSection==='inicio'?'teoria':state.lastSection}">Continuar estudiando</button><button class="btn accent" id="homeRandom">Pregunta aleatoria</button><button class="btn" data-section="simulacro">Iniciar simulacro</button></div></div>
 <aside class="hero-note"><div class="eyebrow">Hoy</div><h2 style="font-family:Georgia,serif">Qué estudiar primero</h2><p class="kicker">Prioridad calculada por frecuencia, orden de dependencias y progreso.</p>${pri.slice(0,3).map((t,i)=>`<div class="priority-row"><span class="priority-rank">${i+1}</span><div><b>${esc(t.nombre)}</b><div class="bar"><span style="width:${t.score}%"></span></div></div><button class="btn small" data-topic-jump="${t.id}">Abrir</button></div>`).join('')}</aside></div>
 <div class="grid-2"><section class="panel editorial"><h2>Situación actual</h2><div class="metric-grid"><div class="metric"><b>${p.sDone}</b><span>habilidades dominadas</span></div><div class="metric"><b>${skills.length-p.sDone}</b><span>habilidades pendientes</span></div><div class="metric"><b>${p.eDone}</b><span>ejercicios resueltos</span></div><div class="metric"><b>${p.wDone}</b><span>talleres resueltos</span></div></div></section>
 <section class="panel"><h2>Temas más frecuentes</h2>${top.map((t,i)=>`<div class="priority-row"><span style="width:12px;height:38px;border-radius:8px;background:${topicColor[t.id]}"></span><div><b>${esc(t.nombre)}</b><small>${STATS.frecuencia_por_tema[t.id]||0} apariciones · progreso ${topicProgress(t.id)}%</small></div><button class="btn small" data-topic-jump="${t.id}">Ver</button></div>`).join('')}</section></div>`;
 document.getElementById('sec-inicio').innerHTML=html;bindNav();document.getElementById('homeRandom').onclick=()=>{theoryCurrent=questions[Math.floor(Math.random()*questions.length)]?.id;navTo('teoria')};
}
function renderTopics(){
 const selected=state.lastTopic||topicPriorities()[0]?.id;const t=topicMap[selected]; if(!t)return;
 const sub=KB.subtemas.filter(s=>s.tema===t.id), qs=questions.filter(q=>q.tema===t.id), es=exercises.filter(e=>e.tema===t.id), sk=skills.filter(s=>s.tema===t.id);
 const dTheory=(t.documentos_teoricos||[]).map(id=>docs[id]).filter(Boolean), dWork=(t.talleres||[]).map(id=>docs[id]).filter(Boolean);
 const list=topics.map(x=>`<button class="topic-card ${x.id===selected?'active':''}" style="${topicStyle(x.id)}" data-topic-jump="${x.id}"><strong>${esc(x.nombre)}</strong><small>${STATS.cantidad_de_preguntas_por_tema[x.id]||0} preguntas · ${STATS.cantidad_de_ejercicios_por_tema[x.id]||0} ejercicios</small><div class="bar" style="margin-top:12px"><span style="width:${topicProgress(x.id)}%"></span></div></button>`).join('');
 const html=sectionHeader('Navegación académica','Temas','Entrá por el concepto que querés dominar y saltá directamente a teoría, práctica o mini prueba.')+`<div class="topic-strip">${list}</div><div style="height:18px"></div>
 <div class="topic-detail-head" style="${topicStyle(t.id)}"><small>Frecuencia ${STATS.frecuencia_por_tema[t.id]||0} · progreso ${topicProgress(t.id)}%</small><h2>${esc(t.nombre)}</h2><p>${esc(t.descripcion_corta||'Tema identificado en las fuentes del curso.')}</p><div class="quick-actions"><button class="btn" id="topicTheory">Estudiar teoría</button><button class="btn" id="topicQuestions">Practicar preguntas</button><button class="btn" id="topicExercises">Practicar ejercicios</button><button class="btn" id="topicWorkshops">Ver talleres</button><button class="btn accent" id="topicMini">Mini prueba</button></div></div>
 <div class="topic-columns"><section class="panel"><h3>Subtemas y habilidades</h3><div class="chips">${sub.map(x=>chip(x.nombre)).join('')}</div><div class="mini-list">${sk.map(x=>`<div class="mini-row" style="${topicStyle(t.id)}"><b>${esc(x.nombre)}</b><div class="muted">${x.ejercicios?.length||0} ejercicios · estado ${state.skillStatus[x.id]||'no iniciada'}</div></div>`).join('')||'<p class="muted">Sin habilidades explícitas.</p>'}</div></section>
 <section class="panel"><h3>Fuentes asociadas</h3><p><b>${dTheory.length}</b> notas · <b>${dWork.length}</b> talleres · <b>${t.parciales?.length||0}</b> parciales · <b>${t.examenes?.length||0}</b> exámenes</p><div class="mini-list">${[...dTheory,...dWork].slice(0,8).map(d=>`<div class="mini-row" style="${topicStyle(t.id)}"><a href="${esc(d.link)}" target="_blank" rel="noopener"><b>${esc(d.nombre)}</b></a><div class="muted">${esc(sourceLabel[d.source_type]||d.tipo||'Fuente')}</div></div>`).join('')}</div></section>
 <section class="panel"><h3>Preguntas teóricas</h3>${qs.slice(0,6).map(q=>`<button class="list-item" data-open-question="${q.id}"><strong>${esc(q.texto_completo.slice(0,120))}${q.texto_completo.length>120?'…':''}</strong><small>${q.anio||'s/a'} · ${q.solucion_oficial?'solución oficial':'sin solución oficial'}</small></button>`).join('')||'<p class="muted">No hay preguntas clasificadas.</p>'}</section>
 <section class="panel"><h3>Ejercicios</h3>${es.slice(0,6).map(e=>`<button class="list-item" data-open-exercise="${e.id}"><strong>${esc((e.encabezado_fuente||e.enunciado_completo).slice(0,120))}</strong><small>${sourceLabel[sourceType(e)]||sourceType(e)} · ${difficulty(e)}</small></button>`).join('')||'<p class="muted">No hay ejercicios clasificados.</p>'}</section></div>`;
 document.getElementById('sec-temas').innerHTML=html;bindNav();
 document.getElementById('topicTheory').onclick=()=>{state.filters.theory={topic:t.id};theoryCurrent=null;navTo('teoria')};document.getElementById('topicQuestions').onclick=()=>{state.filters.bank={topic:t.id};navTo('banco')};document.getElementById('topicExercises').onclick=()=>{state.filters.practice={topic:t.id};practiceCurrent=null;navTo('practica')};document.getElementById('topicWorkshops').onclick=()=>{state.filters.workshops={topic:t.id};navTo('talleres')};document.getElementById('topicMini').onclick=()=>{state.filters.sim={topic:t.id,count:5,mode:'mixto'};navTo('simulacro')};
 document.querySelectorAll('[data-open-question]').forEach(b=>b.onclick=()=>{bankSelected=b.dataset.openQuestion;state.filters.bank={topic:t.id};navTo('banco')});document.querySelectorAll('[data-open-exercise]').forEach(b=>b.onclick=()=>{explorerSelected=b.dataset.openExercise;state.filters.explorer={topic:t.id};navTo('explorador')});
}
function renderSkills(){
 const rows=skills.map(s=>{const relatedDocs=uniq([...(s.documentos||[])]).map(id=>docs[id]).filter(Boolean);return `<div class="skill-row"><div><h3 style="margin:0">${esc(s.nombre)}</h3><div class="chips">${chip(topicName(s.tema))}${chip(s.subtema||'')}${chip(`${s.ejercicios?.length||0} ejercicios`)}${chip(`${s.preguntas?.length||0} preguntas`)}</div><p class="muted">Prerrequisitos: ${esc((GRAPH.relaciones||[]).filter(r=>r.hacia===s.id||r.destino===s.id).slice(0,3).map(r=>r.desde||r.origen).join(', ')||'según el orden del tema')}</p><small>${relatedDocs.filter(d=>['parcial','examen'].includes(d.source_type)).length} evaluaciones relacionadas</small></div><select class="status-select" data-skill-status="${s.id}"><option value="no_iniciada">No iniciada</option><option value="en_progreso">En progreso</option><option value="dominada">Dominada</option></select></div>`}).join('');
 document.getElementById('sec-habilidades').innerHTML=sectionHeader('Capacidades evaluables','Habilidades','Marcá tu estado. También se actualizan al practicar preguntas y ejercicios.')+`<section class="panel">${rows}</section>`;
 document.querySelectorAll('[data-skill-status]').forEach(sel=>{sel.value=state.skillStatus[sel.dataset.skillStatus]||'no_iniciada';sel.onchange=()=>{state.skillStatus[sel.dataset.skillStatus]=sel.value;save();toast('Estado actualizado')}})
}
function theoryFilters(){return state.filters.theory||{topic:'',subtopic:'',difficulty:'',source:'',failed:false,frequent:false,random:false}}
function filteredQuestions(){const f=theoryFilters();return questions.filter(q=>(!f.topic||q.tema===f.topic)&&(!f.subtopic||q.subtema===f.subtopic)&&(!f.difficulty||difficulty(q)===f.difficulty)&&(!f.source||sourceType(q)===f.source)&&(!f.failed||(state.questionResults[q.id]?.wrong||0)>0)&&(!f.frequent||questionFrequency(q)>1))}
function qHint1(q){return `Pista generada: ubicá la respuesta dentro de “${topicName(q.tema)}” y, en particular, “${q.subtema||'el subtema asociado'}”. Definí primero el concepto central antes de justificar.`}
function qHint2(q){const text=q.texto_completo.toLowerCase();let guide='Organizá la respuesta como: definición, funcionamiento y consecuencia.';if(/compare|diferencia/.test(text))guide='Separá criterios de comparación y cerrá con la diferencia decisiva.';else if(/describa|explique/.test(text))guide='Indicá qué es, cómo funciona y para qué se usa.';else if(/implemente|construya/.test(text))guide='Identificá entradas, salidas, ecuación de próximo estado o selección, y luego el circuito.';else if(/calcule|indique/.test(text))guide='Anotá datos, fórmula o regla y justificá cada cantidad de bits.';return 'Pista generada: '+guide}
function relatedTheory(q){const t=topicMap[q.tema];const ds=(t?.documentos_teoricos||[]).map(id=>docs[id]).filter(Boolean);if(!ds.length)return 'No hay una nota teórica asociada de forma explícita.';return ds.slice(0,2).map(d=>`${d.nombre}:\n${(d.contenido_completo||'').slice(0,700)}`).join('\n\n')}
function renderQuestionDetail(q,mode='theory'){
 if(!q)return '<div class="empty">No hay preguntas para estos filtros.</div>';const d=docOf(q), st=getQuestionState(q.id);
 return `<div class="chips">${chip(topicName(q.tema),'dark')}${chip(q.subtema||'')}${chip(sourceLabel[sourceType(q)]||sourceType(q))}${chip(String(q.anio||'sin año'))}${chip(difficulty(q))}${q.solucion_oficial?chip('Solución oficial','official'):chip('Sin solución oficial','warning')}</div><div class="question-text" style="${topicStyle(q.tema)}">${fmt(q.texto_completo)}</div><div class="quick-actions"><button class="btn" data-q-action="hint1">Pista 1</button><button class="btn" data-q-action="hint2">Pista 2</button><button class="btn primary" data-q-action="answer">Ver respuesta</button>${mode==='theory'?'<button class="btn good" data-q-action="known">La sabía</button><button class="btn bad" data-q-action="unknown">No la sabía</button>':''}<button class="btn" data-q-action="mark">${state.markedQuestions.includes(q.id)?'Quitar marca':'Marcar para repasar'}</button></div><div id="qReveal"></div><p class="counter">Estado personal: ${st.replaceAll('_',' ')} · fuente: <a href="${esc(q.link||d.link||'#')}" target="_blank" rel="noopener">${esc(d.nombre||'documento')}</a></p>`
}
function bindQuestionActions(q,nextFn,mode='theory'){
 document.querySelectorAll('[data-q-action]').forEach(b=>b.onclick=()=>{const box=document.getElementById('qReveal');const a=b.dataset.qAction;if(a==='hint1')box.innerHTML=`<div class="hint-box">${fmt(qHint1(q))}</div>`;if(a==='hint2')box.innerHTML=`<div class="hint-box">${fmt(qHint2(q))}</div>`;if(a==='answer'){if(q.solucion){box.innerHTML=`<div class="solution-box"><b>${q.solucion_oficial?'Solución oficial':'Síntesis teórica'}</b><br><br>${fmt(q.solucion)}${q.solucion_nota?`<br><br><small>${esc(q.solucion_nota)}</small>`:''}${q.solucion_imagen?`<img class="official-image" src="${q.solucion_imagen}" alt="Diagrama de la solución oficial">`:''}</div>`}else{box.innerHTML=`<div class="solution-box"><b>Sin solución oficial disponible.</b><br><br><span class="muted">Referencia teórica relacionada:</span><br>${fmt(relatedTheory(q))}</div>`}}if(a==='known'||a==='unknown'){const r=state.questionResults[q.id]||{correct:0,wrong:0};a==='known'?r.correct++:r.wrong++;r.last=Date.now();state.questionResults[q.id]=r;(q.habilidades||[]).forEach(id=>state.skillStatus[id]=a==='known'?'en_progreso':(state.skillStatus[id]||'no_iniciada'));save();toast(a==='known'?'Registrada como sabida':'Marcada para repasar');nextFn?.()}if(a==='mark'){state.markedQuestions=state.markedQuestions.includes(q.id)?state.markedQuestions.filter(x=>x!==q.id):[...state.markedQuestions,q.id];save();mode==='theory'?renderTheory():renderBank()}})
}
function renderTheory(){
 const f=theoryFilters(), list=filteredQuestions();if(!theoryCurrent||!list.some(q=>q.id===theoryCurrent))theoryCurrent=(f.random?list[Math.floor(Math.random()*list.length)]:list[0])?.id;const q=questions.find(x=>x.id===theoryCurrent);
 const sub=uniq(questions.filter(x=>!f.topic||x.tema===f.topic).map(x=>x.subtema)).sort();
 const html=sectionHeader('Repaso activo','Teoría rápida','La pregunta ocupa el centro. Las pistas son progresivas y la fuente queda visible.')+`<div class="split"><aside><div class="filters" style="grid-template-columns:1fr"><div class="field"><label>Tema</label><select id="tfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div class="field"><label>Subtema</label><select id="tfSub">${optionList(sub,f.subtopic)}</select></div><div class="field"><label>Dificultad</label><select id="tfDiff">${optionList(['Baja','Media','Alta'],f.difficulty)}</select></div><div class="field"><label>Fuente</label><select id="tfSource">${optionList(['nota','practico','taller','parcial','examen'].map(x=>({value:x,label:sourceLabel[x]})),f.source)}</select></div><label class="checkline"><input id="tfFailed" type="checkbox" ${f.failed?'checked':''}>Solo las que fallé</label><label class="checkline"><input id="tfFreq" type="checkbox" ${f.frequent?'checked':''}>Solo frecuentes</label><label class="checkline"><input id="tfRandom" type="checkbox" ${f.random?'checked':''}>Orden aleatorio</label></div><div class="panel"><b>${list.length}</b> preguntas disponibles<br><button class="btn small" id="nextTheory" style="margin-top:10px">Siguiente</button></div></aside><article class="detail">${renderQuestionDetail(q)}</article></div>`;
 document.getElementById('sec-teoria').innerHTML=html;
 const update=()=>{state.filters.theory={topic:$id('tfTopic').value,subtopic:$id('tfSub').value,difficulty:$id('tfDiff').value,source:$id('tfSource').value,failed:$id('tfFailed').checked,frequent:$id('tfFreq').checked,random:$id('tfRandom').checked};theoryCurrent=null;save();renderTheory()};['tfTopic','tfSub','tfDiff','tfSource','tfFailed','tfFreq','tfRandom'].forEach(id=>document.getElementById(id).onchange=update);document.getElementById('nextTheory').onclick=()=>nextTheory();if(q)bindQuestionActions(q,nextTheory,'theory');
}
function nextTheory(){const list=filteredQuestions();if(!list.length)return;const i=list.findIndex(q=>q.id===theoryCurrent);theoryCurrent=(theoryFilters().random?list[Math.floor(Math.random()*list.length)]:list[(i+1)%list.length]).id;state.lastQuestion=theoryCurrent;save();renderTheory()}
function practiceFilters(){return state.filters.practice||{topic:'',subtopic:'',skill:'',source:'',difficulty:'',solution:'',random:false}}
function filteredExercises(){const f=practiceFilters();return exercises.filter(e=>(!f.topic||e.tema===f.topic)&&(!f.subtopic||e.subtema===f.subtopic)&&(!f.skill||(e.habilidades||[]).includes(f.skill))&&(!f.source||sourceType(e)===f.source)&&(!f.difficulty||difficulty(e)===f.difficulty)&&(!f.solution||(f.solution==='yes'?e.solucion_oficial:!e.solucion_oficial)))}
function exHint1(e){return `Pista generada: el ejercicio trabaja ${topicName(e.tema)}${e.subtema?' — '+e.subtema:''}. Antes de operar, identificá datos, representación y salida pedida.`}
function exHint2(e){const hs=(e.habilidades||[]).map(id=>skillMap[id]?.nombre).filter(Boolean);return `Pista generada: dividí el procedimiento en bloques: ${hs.length?hs.join('; '):'modelar, calcular y verificar'}. Comprobá tamaños, unidades y casos límite.`}
function procedure(e){return `Procedimiento orientativo (no oficial):\n1. Reescribí las entradas y la salida esperada.\n2. Aplicá la habilidad principal: ${(e.habilidades||[]).map(id=>skillMap[id]?.nombre).filter(Boolean).join(', ')||'la técnica del tema'}.\n3. Verificá cantidad de bits, rangos y estado final.\n4. Compará con la fuente oficial solo después de intentar.`}
function renderExerciseDetail(e,mode='practice'){
 if(!e)return '<div class="empty">No hay ejercicios para estos filtros.</div>';const d=docOf(e);return `<div class="chips">${chip(topicName(e.tema),'dark')}${chip(e.subtema||'')}${chip(sourceLabel[sourceType(e)]||sourceType(e))}${chip(String(e.anio||'sin año'))}${chip(difficulty(e))}${e.solucion_oficial?chip('Solución oficial','official'):chip('Sin solución oficial','warning')}</div><div class="exercise-text" style="${topicStyle(e.tema)}">${fmt(e.enunciado_completo)}</div><div class="quick-actions"><button class="btn" data-e-action="hint1">Pista 1</button><button class="btn" data-e-action="hint2">Pista 2</button><button class="btn" data-e-action="procedure">Ver procedimiento</button>${e.solucion_oficial?'<button class="btn primary" data-e-action="solution">Ver solución oficial</button>':'<button class="btn" disabled>Sin solución oficial disponible</button>'}${mode==='practice'?'<button class="btn good" data-e-action="solved">Lo resolví</button><button class="btn bad" data-e-action="review">Necesito repasar</button>':''}<button class="btn" data-e-action="favorite">${state.favorites.includes(e.id)?'Quitar favorito':'Marcar favorito'}</button></div><div id="eReveal"></div><p class="counter">Fuente: <a href="${esc(e.link||d.link||'#')}" target="_blank" rel="noopener">${esc(d.nombre||'documento')}</a></p>`}
function bindExerciseActions(e,nextFn,mode='practice'){
 document.querySelectorAll('[data-e-action]').forEach(b=>b.onclick=()=>{const box=document.getElementById('eReveal');const a=b.dataset.eAction;if(a==='hint1')box.innerHTML=`<div class="hint-box">${fmt(exHint1(e))}</div>`;if(a==='hint2')box.innerHTML=`<div class="hint-box">${fmt(exHint2(e))}</div>`;if(a==='procedure')box.innerHTML=`<div class="procedure-box">${fmt(procedure(e))}</div>`;if(a==='solution')box.innerHTML=`<div class="solution-box"><b>Solución oficial</b><br><br>${fmt(e.solucion||'El documento oficial contiene una solución gráfica o no extraíble como texto. Abrí la fuente original.')}</div>`;if(a==='solved'||a==='review'){state.exerciseStatus[e.id]=a==='solved'?'resuelto':'repasar';(e.habilidades||[]).forEach(id=>state.skillStatus[id]=a==='solved'?'en_progreso':(state.skillStatus[id]||'no_iniciada'));save();toast(a==='solved'?'Ejercicio resuelto':'Marcado para repasar');nextFn?.()}if(a==='favorite'){state.favorites=state.favorites.includes(e.id)?state.favorites.filter(x=>x!==e.id):[...state.favorites,e.id];save();mode==='practice'?renderPractice():renderExplorer()}})
}
function renderPractice(){
 const f=practiceFilters(), list=filteredExercises();if(!practiceCurrent||!list.some(e=>e.id===practiceCurrent))practiceCurrent=(f.random?list[Math.floor(Math.random()*list.length)]:list[0])?.id;const e=exercises.find(x=>x.id===practiceCurrent);const sub=uniq(exercises.filter(x=>!f.topic||x.tema===f.topic).map(x=>x.subtema)).sort();
 document.getElementById('sec-practica').innerHTML=sectionHeader('Entrenamiento','Práctica','Ejercicios completos, pistas conceptuales y soluciones solo cuando están identificadas como oficiales.')+`<div class="split"><aside><div class="filters" style="grid-template-columns:1fr"><div class="field"><label>Tema</label><select id="pfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div class="field"><label>Subtema</label><select id="pfSub">${optionList(sub,f.subtopic)}</select></div><div class="field"><label>Habilidad</label><select id="pfSkill">${optionList(skills.map(s=>({value:s.id,label:s.nombre})),f.skill)}</select></div><div class="field"><label>Origen</label><select id="pfSource">${optionList(['practico','taller','parcial','examen'].map(x=>({value:x,label:sourceLabel[x]})),f.source)}</select></div><div class="field"><label>Dificultad</label><select id="pfDiff">${optionList(['Baja','Media','Alta'],f.difficulty)}</select></div><div class="field"><label>Solución oficial</label><select id="pfSol">${optionList([{value:'yes',label:'Con solución oficial'},{value:'no',label:'Sin solución oficial'}],f.solution)}</select></div><label class="checkline"><input id="pfRandom" type="checkbox" ${f.random?'checked':''}>Aleatorio</label></div><div class="panel"><b>${list.length}</b> ejercicios disponibles<br><button class="btn small" id="nextPractice" style="margin-top:10px">Siguiente</button></div></aside><article class="detail">${renderExerciseDetail(e)}</article></div>`;
 const update=()=>{state.filters.practice={topic:$id('pfTopic').value,subtopic:$id('pfSub').value,skill:$id('pfSkill').value,source:$id('pfSource').value,difficulty:$id('pfDiff').value,solution:$id('pfSol').value,random:$id('pfRandom').checked};practiceCurrent=null;save();renderPractice()};['pfTopic','pfSub','pfSkill','pfSource','pfDiff','pfSol','pfRandom'].forEach(id=>document.getElementById(id).onchange=update);document.getElementById('nextPractice').onclick=nextPractice;if(e)bindExerciseActions(e,nextPractice,'practice');
}
function nextPractice(){const list=filteredExercises();if(!list.length)return;const i=list.findIndex(e=>e.id===practiceCurrent);practiceCurrent=(practiceFilters().random?list[Math.floor(Math.random()*list.length)]:list[(i+1)%list.length]).id;state.lastExercise=practiceCurrent;save();renderPractice()}
function renderWorkshops(){
 const f=state.filters.workshops||{topic:''};const workshopDocs=KB.documentos.filter(d=>d.source_type==='taller'||d.carpeta==='Taller').filter(d=>!f.topic||(d.temas||[]).includes(f.topic));
 document.getElementById('sec-talleres').innerHTML=sectionHeader('Puente hacia la evaluación','Talleres','Material prioritario de entrenamiento. No se presentan soluciones inventadas.')+`<div class="filters"><div class="field"><label>Tema</label><select id="wfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div></div><div class="grid-3">${workshopDocs.map(d=>{const t=d.tema_principal||d.temas?.[0], rels=(REL.relaciones||[]).filter(r=>r.origen===d.id||r.destino===d.id).slice(0,5);return `<article class="panel workshop" style="${topicStyle(t)}"><div class="chips">${chip(topicName(t))}${chip(String(d.anio||'s/a'))}${chip(state.workshopStatus[d.id]||'pendiente')}</div><h3>${esc(d.nombre)}</h3><p class="muted">${(d.subtemas||[]).map(esc).join(' · ')}</p><div class="source-content" style="max-height:180px">${fmt((d.contenido_completo||'').slice(0,1400))}</div><p><b>Del taller al examen</b></p>${rels.length?rels.map(r=>`<div class="mini-row" style="${topicStyle(t)}">${esc(r.tipo||'relación')} · ${esc(r.evidencia||'tema compartido')}</div>`).join(''):'<p class="muted">Sin relación explícita registrada.</p>'}<div class="quick-actions"><select class="status-select" data-workshop="${d.id}"><option>pendiente</option><option>intentado</option><option>resuelto</option><option>revisar</option></select><a class="btn small" href="${esc(d.link)}" target="_blank" rel="noopener">Abrir fuente</a></div></article>`}).join('')||'<div class="empty">No hay talleres con ese filtro.</div>'}</div>`;
 document.getElementById('wfTopic').onchange=e=>{state.filters.workshops={topic:e.target.value};save();renderWorkshops()};document.querySelectorAll('[data-workshop]').forEach(s=>{s.value=state.workshopStatus[s.dataset.workshop]||'pendiente';s.onchange=()=>{state.workshopStatus[s.dataset.workshop]=s.value;save();toast('Taller actualizado')}})
}
function bankFilters(){return state.filters.bank||{search:'',topic:'',subtopic:'',source:'',year:'',frequency:'',personal:''}}
function bankList(){const f=bankFilters();const term=f.search.toLowerCase();return questions.filter(q=>(!term||q.texto_completo.toLowerCase().includes(term))&&(!f.topic||q.tema===f.topic)&&(!f.subtopic||q.subtema===f.subtopic)&&(!f.source||sourceType(q)===f.source)&&(!f.year||String(q.anio)===f.year)&&(!f.frequency||(f.frequency==='frequent'?questionFrequency(q)>1:questionFrequency(q)<=1))&&(!f.personal||getQuestionState(q.id)===f.personal))}
function renderBank(){
 const f=bankFilters(), list=bankList();if(!bankSelected||!list.some(q=>q.id===bankSelected))bankSelected=list[0]?.id;const q=questions.find(x=>x.id===bankSelected);const sub=uniq(questions.filter(x=>!f.topic||x.tema===f.topic).map(x=>x.subtema)).sort();
 document.getElementById('sec-banco').innerHTML=sectionHeader('Archivo navegable','Banco de preguntas','La búsqueda y los filtros permanecen intactos al abrir una pregunta.')+`<div class="filters"><div class="field"><label>Buscar texto</label><input id="bfSearch" value="${esc(f.search)}" placeholder="Palabras de la pregunta"></div><div class="field"><label>Tema</label><select id="bfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div class="field"><label>Subtema</label><select id="bfSub">${optionList(sub,f.subtopic)}</select></div><div class="field"><label>Fuente</label><select id="bfSource">${optionList(['nota','practico','taller','parcial','examen'].map(x=>({value:x,label:sourceLabel[x]})),f.source)}</select></div><div class="field"><label>Año</label><select id="bfYear">${optionList(yearValues(questions).map(String),f.year)}</select></div><div class="field"><label>Frecuencia</label><select id="bfFreq">${optionList([{value:'frequent',label:'Frecuentes'},{value:'unique',label:'Aparición única'}],f.frequency)}</select></div><div class="field"><label>Estado personal</label><select id="bfPersonal">${optionList([{value:'no_iniciada',label:'No iniciada'},{value:'dominada',label:'Dominada'},{value:'repasar',label:'Repasar'}],f.personal)}</select></div></div><div class="search-summary"><span>${list.length} resultados</span><span>Filtros preservados</span></div><div class="split"><div class="list-panel">${list.map(x=>`<button class="list-item ${x.id===bankSelected?'active':''}" data-bank-id="${x.id}"><strong>${esc(x.texto_completo.slice(0,145))}${x.texto_completo.length>145?'…':''}</strong><small>${esc(topicName(x.tema))} · ${x.anio||'s/a'}</small></button>`).join('')||'<div class="empty">Sin resultados.</div>'}</div><article class="detail">${renderQuestionDetail(q,'bank')}</article></div>`;
 const update=()=>{state.filters.bank={search:$id('bfSearch').value,topic:$id('bfTopic').value,subtopic:$id('bfSub').value,source:$id('bfSource').value,year:$id('bfYear').value,frequency:$id('bfFreq').value,personal:$id('bfPersonal').value};save();renderBank()};document.getElementById('bfSearch').oninput=update;['bfTopic','bfSub','bfSource','bfYear','bfFreq','bfPersonal'].forEach(id=>document.getElementById(id).onchange=update);document.querySelectorAll('[data-bank-id]').forEach(b=>b.onclick=()=>{bankSelected=b.dataset.bankId;renderBank()});if(q)bindQuestionActions(q,null,'bank');
}
function explorerFilters(){return state.filters.explorer||{search:'',topic:'',subtopic:'',skill:'',source:'',year:'',difficulty:'',solution:''}}
function explorerList(){const f=explorerFilters(),term=f.search.toLowerCase();return exercises.filter(e=>(!term||e.enunciado_completo.toLowerCase().includes(term))&&(!f.topic||e.tema===f.topic)&&(!f.subtopic||e.subtema===f.subtopic)&&(!f.skill||(e.habilidades||[]).includes(f.skill))&&(!f.source||sourceType(e)===f.source)&&(!f.year||String(e.anio)===f.year)&&(!f.difficulty||difficulty(e)===f.difficulty)&&(!f.solution||(f.solution==='yes'?e.solucion_oficial:!e.solucion_oficial)))}
function renderExplorer(){
 const f=explorerFilters(), list=explorerList();if(!explorerSelected||!list.some(e=>e.id===explorerSelected))explorerSelected=list[0]?.id;const e=exercises.find(x=>x.id===explorerSelected);const sub=uniq(exercises.filter(x=>!f.topic||x.tema===f.topic).map(x=>x.subtema)).sort();
 document.getElementById('sec-explorador').innerHTML=sectionHeader('Búsqueda precisa','Explorador de ejercicios','Filtrá por tema, habilidad, origen, año y disponibilidad de solución.')+`<div class="filters"><div class="field"><label>Buscar texto</label><input id="efSearch" value="${esc(f.search)}"></div><div class="field"><label>Tema</label><select id="efTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div class="field"><label>Subtema</label><select id="efSub">${optionList(sub,f.subtopic)}</select></div><div class="field"><label>Habilidad</label><select id="efSkill">${optionList(skills.map(s=>({value:s.id,label:s.nombre})),f.skill)}</select></div><div class="field"><label>Origen</label><select id="efSource">${optionList(['practico','taller','parcial','examen'].map(x=>({value:x,label:sourceLabel[x]})),f.source)}</select></div><div class="field"><label>Año</label><select id="efYear">${optionList(yearValues(exercises).map(String),f.year)}</select></div><div class="field"><label>Dificultad</label><select id="efDiff">${optionList(['Baja','Media','Alta'],f.difficulty)}</select></div><div class="field"><label>Solución</label><select id="efSol">${optionList([{value:'yes',label:'Oficial'},{value:'no',label:'Sin oficial'}],f.solution)}</select></div></div><div class="search-summary"><span>${list.length} resultados</span><span>Lista y filtros persistentes</span></div><div class="split"><div class="list-panel">${list.map(x=>`<button class="list-item ${x.id===explorerSelected?'active':''}" data-explorer-id="${x.id}"><strong>${esc((x.encabezado_fuente||x.enunciado_completo).slice(0,145))}</strong><small>${esc(topicName(x.tema))} · ${sourceLabel[sourceType(x)]||sourceType(x)} · ${x.anio||'s/a'}</small></button>`).join('')||'<div class="empty">Sin resultados.</div>'}</div><article class="detail">${renderExerciseDetail(e,'explorer')}</article></div>`;
 const update=()=>{state.filters.explorer={search:$id('efSearch').value,topic:$id('efTopic').value,subtopic:$id('efSub').value,skill:$id('efSkill').value,source:$id('efSource').value,year:$id('efYear').value,difficulty:$id('efDiff').value,solution:$id('efSol').value};save();renderExplorer()};document.getElementById('efSearch').oninput=update;['efTopic','efSub','efSkill','efSource','efYear','efDiff','efSol'].forEach(id=>document.getElementById(id).onchange=update);document.querySelectorAll('[data-explorer-id]').forEach(b=>b.onclick=()=>{explorerSelected=b.dataset.explorerId;renderExplorer()});if(e)bindExerciseActions(e,null,'explorer');
}
const checklistStates=['no_iniciado','visto','practicado','dominado'];
function checklistItems(){const general=[['general_theory','Teoría mínima','Repasar definiciones de los temas más frecuentes.'],['general_exercises','Ejercicios esenciales','Resolver al menos un ejercicio oficial por tema prioritario.'],['general_workshops','Talleres prioritarios','Intentar los talleres vinculados a parciales y exámenes.'],['general_partials','Parciales recomendados','Practicar parciales recientes con solución.'],['general_exams','Exámenes recomendados','Resolver exámenes completos con tiempo.'],['general_errors','Errores frecuentes','Revisar preguntas marcadas y ejercicios en repaso.'],['general_sim','Simulacro final','Completar un simulacro mixto.']].map(x=>({id:x[0],title:x[1],desc:x[2],group:'General'}));const ts=topics.flatMap(t=>[{id:'topic_theory_'+t.id,title:'Teoría de '+t.nombre,desc:'Comprender conceptos y definiciones.',group:t.nombre},{id:'topic_practice_'+t.id,title:'Práctica de '+t.nombre,desc:'Resolver ejercicios del tema.',group:t.nombre}]);const ss=skills.map(s=>({id:'skill_'+s.id,title:s.nombre,desc:'Habilidad evaluable.',group:'Habilidades'}));return [...general,...ts,...ss]}
function renderChecklist(){const items=checklistItems();const groups=Object.groupBy?Object.groupBy(items,x=>x.group):items.reduce((a,x)=>((a[x.group]??=[]).push(x),a),{});document.getElementById('sec-checklist').innerHTML=sectionHeader('Plan verificable','Checklist','Estados guardados en el navegador: no iniciado, visto, practicado y dominado.')+Object.entries(groups).map(([g,arr])=>`<section class="panel checklist-group"><h2>${esc(g)}</h2>${arr.map(x=>`<div class="check-item"><div><b>${esc(x.title)}</b><div class="muted">${esc(x.desc)}</div></div><select data-check="${x.id}">${checklistStates.map(s=>`<option value="${s}">${s.replaceAll('_',' ')}</option>`).join('')}</select></div>`).join('')}</section>`).join('');document.querySelectorAll('[data-check]').forEach(s=>{s.value=state.checklist[s.dataset.check]||'no_iniciado';s.onchange=()=>{state.checklist[s.dataset.check]=s.value;save()}})}
function simFilters(){return state.filters.sim||{count:10,mode:'mixto',topic:'',frequent:false,weak:false,official:false,workshops:false}}
function renderSimulation(){if(sim?.active)return renderSimQuestion();if(sim?.finished)return renderSimResult();const f=simFilters();document.getElementById('sec-simulacro').innerHTML=sectionHeader('Prueba final','Simulacro de examen','Configuralo y resolvé una pregunta a la vez. La evaluación es por auto-corrección contra la solución disponible.')+`<section class="panel sim-card"><div class="grid-2"><div class="field"><label>Cantidad</label><select id="sfCount">${[5,10,15,20].map(n=>`<option ${n==f.count?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Modo</label><select id="sfMode"><option value="teoria" ${f.mode==='teoria'?'selected':''}>Solo teoría</option><option value="practica" ${f.mode==='practica'?'selected':''}>Solo práctica</option><option value="mixto" ${f.mode==='mixto'?'selected':''}>Mixto</option></select></div><div class="field"><label>Tema</label><select id="sfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div></div></div><label class="checkline"><input id="sfFreq" type="checkbox" ${f.frequent?'checked':''}>Priorizar material frecuente</label><label class="checkline"><input id="sfWeak" type="checkbox" ${f.weak?'checked':''}>Priorizar habilidades débiles</label><label class="checkline"><input id="sfOfficial" type="checkbox" ${f.official?'checked':''}>Incluir solo material con solución oficial</label><label class="checkline"><input id="sfWork" type="checkbox" ${f.workshops?'checked':''}>Incluir talleres como entrenamiento</label><div class="quick-actions"><button class="btn accent" id="startSim">Comenzar simulacro</button></div></section>`;document.getElementById('startSim').onclick=startSimulation}
function startSimulation(){const f={count:+$id('sfCount').value,mode:$id('sfMode').value,topic:$id('sfTopic').value,frequent:$id('sfFreq').checked,weak:$id('sfWeak').checked,official:$id('sfOfficial').checked,workshops:$id('sfWork').checked};state.filters.sim=f;save();let pool=[];if(f.mode!=='practica')pool.push(...questions.map(x=>({kind:'q',id:x.id,topic:x.tema,freq:questionFrequency(x),official:!!x.solucion_oficial})));if(f.mode!=='teoria')pool.push(...exercises.filter(x=>f.workshops||sourceType(x)!=='taller').map(x=>({kind:'e',id:x.id,topic:x.tema,freq:x.frecuencia||1,official:!!x.solucion_oficial})));pool=pool.filter(x=>(!f.topic||x.topic===f.topic)&&(!f.official||x.official));if(f.frequent)pool.sort((a,b)=>b.freq-a.freq);else pool.sort(()=>Math.random()-.5);if(f.weak)pool.sort((a,b)=>{const wa=a.kind==='q'?(state.questionResults[a.id]?.wrong||0):(isExerciseForReview(a.id)?1:0),wb=b.kind==='q'?(state.questionResults[b.id]?.wrong||0):(isExerciseForReview(b.id)?1:0);return wb-wa||Math.random()-.5});pool=pool.slice(0,f.count);if(!pool.length){toast('No hay material para esa configuración');return}sim={active:true,finished:false,items:pool,index:0,answers:[],revealed:false,reviewSaved:false,started:Date.now()};renderSimulation()}
function renderSimQuestion(){const item=sim.items[sim.index], obj=item.kind==='q'?questions.find(x=>x.id===item.id):exercises.find(x=>x.id===item.id);const pct=Math.round(100*sim.index/sim.items.length);const alreadySaved=item.kind==='e'?isExerciseForReview(item.id):state.markedQuestions.includes(item.id);sim.reviewSaved=!!(sim.reviewSaved||alreadySaved);document.getElementById('sec-simulacro').innerHTML=`${sectionHeader('Simulacro en curso',`Pregunta ${sim.index+1} de ${sim.items.length}`,'No mires la respuesta antes de intentar.')}
 <section class="panel sim-card"><div class="sim-progress"><div class="bar" style="flex:1"><span style="width:${pct}%"></span></div><button class="btn small" id="finishEarly">Finalizar antes</button></div><div class="sim-dots">${sim.items.map((_,i)=>`<span class="sim-dot ${i<sim.index?'done':''} ${i===sim.index?'current':''}"></span>`).join('')}</div><div style="height:16px"></div>${item.kind==='q'?renderQuestionDetail(obj,'sim'):renderExerciseDetail(obj,'sim')}<div class="quick-actions"><button class="btn ${sim.reviewSaved?'good':''}" id="simSaveReview">${item.kind==='e'?(sim.reviewSaved?'Guardado para repaso':'Guardar para repaso'):(sim.reviewSaved?'Teoría guardada':'Guardar teoría para repaso')}</button><button class="btn primary" id="simReveal">Mostrar respuesta</button><button class="btn good ${sim.revealed?'':'hidden'}" id="simRight">Correcta</button><button class="btn bad ${sim.revealed?'':'hidden'}" id="simWrong">Incorrecta</button></div><div id="simRevealBox"></div></section>`;
 document.querySelectorAll('[data-q-action],[data-e-action]').forEach(b=>b.remove());document.getElementById('simSaveReview').onclick=()=>{sim.reviewSaved=true;if(item.kind==='e')setExerciseForReview(item.id,true);else if(!state.markedQuestions.includes(item.id))state.markedQuestions.push(item.id);save();const button=document.getElementById('simSaveReview');button.textContent='Guardado para repaso';button.classList.add('good');toast(item.kind==='e'?'Ejercicio guardado para repaso':'Pregunta guardada para repaso')};document.getElementById('simReveal').onclick=()=>{sim.revealed=true;const box=document.getElementById('simRevealBox');if(item.kind==='q')box.innerHTML=obj.solucion?`<div class="solution-box"><b>${obj.solucion_oficial?'Solución oficial':'Respuesta disponible'}</b><br><br>${fmt(obj.solucion)}${obj.solucion_imagen?`<img class="official-image" src="${obj.solucion_imagen}">`:''}</div>`:`<div class="solution-box">Sin solución oficial. Usá las notas relacionadas para autocorregirte.</div>`;else box.innerHTML=obj.solucion_oficial?`<div class="solution-box"><b>Solución oficial</b><br><br>${fmt(obj.solucion||'Solución gráfica en la fuente original.')}</div>`:`<div class="solution-box">Sin solución oficial disponible.</div>`;document.getElementById('simRight').classList.remove('hidden');document.getElementById('simWrong').classList.remove('hidden')};document.getElementById('simRight').onclick=()=>scoreSim(true);document.getElementById('simWrong').onclick=()=>scoreSim(false);document.getElementById('finishEarly').onclick=finishSim}
function scoreSim(correct){
 const item=sim.items[sim.index],reviewSaved=!!sim.reviewSaved;
 sim.answers.push({...item,correct,doubt:reviewSaved,reviewSaved});
 if(item.kind==='q'){
   const r=state.questionResults[item.id]||{correct:0,wrong:0};correct?r.correct++:r.wrong++;state.questionResults[item.id]=r;
   if(reviewSaved&&!state.markedQuestions.includes(item.id))state.markedQuestions.push(item.id);
 }else{
   if(reviewSaved||!correct)setExerciseForReview(item.id,true);
   else state.exerciseStatus[item.id]='resuelto';
 }
 save();sim.index++;sim.revealed=false;sim.reviewSaved=false;
 if(sim.index>=sim.items.length)finishSim();else renderSimulation();
}
function finishSim(){sim.active=false;sim.finished=true;sim.ended=Date.now();state.simulations.push({date:sim.ended,count:sim.answers.length,correct:sim.answers.filter(x=>x.correct).length,items:sim.answers});save();renderSimulation()}
function renderSimResult(){
 const total=sim.answers.length,ok=sim.answers.filter(x=>x.correct).length,pct=total?Math.round(100*ok/total):0,grade=uyGrade(pct);
 const review=sim.answers.filter(x=>!x.correct||x.doubt),weak=Object.entries(review.reduce((a,x)=>(a[x.topic]=(a[x.topic]||0)+1,a),{})).sort((a,b)=>b[1]-a[1]);
 document.getElementById('sec-simulacro').innerHTML=sectionHeader('Resultado','Simulacro finalizado','')+`<section class="panel sim-card"><div class="sim-grade-result"><div class="score-big">${grade.num}</div><div><h2>${grade.label}</h2><p>${pct}% · ${ok}/${total} correctas</p></div></div><div class="grid-2"><div><h3>Temas a reforzar</h3>${weak.map(([id,n])=>`<div class="priority-row"><span style="width:12px;height:35px;background:${topicColor[id]};border-radius:8px"></span><div><b>${esc(topicName(id))}</b><small>${n} para repasar</small></div><button class="btn small" data-topic-jump="${id}">Abrir</button></div>`).join('')||'<p class="muted">Ninguno.</p>'}</div><div><h3>Marcadas para repasar</h3>${review.map(x=>{const o=x.kind==='q'?questions.find(q=>q.id===x.id):exercises.find(e=>e.id===x.id);return `<div class="mini-row" style="${topicStyle(x.topic)}">${x.doubt?'◆ ':''}${esc((o.texto_completo||o.encabezado_fuente||o.enunciado_completo).slice(0,130))}</div>`}).join('')||'<p class="muted">Ninguna.</p>'}</div></div><div class="quick-actions"><button class="btn accent" id="newSim">Nuevo simulacro</button><button class="btn" data-section="banco">Banco de examen</button></div></section>`;
 document.getElementById('newSim').onclick=()=>{sim=null;renderSimulation()};bindNav();
}
function renderStats(){const p=progress(), histories=[...state.simulations].reverse();const pri=topicPriorities();const rec=pri.filter(t=>topicProgress(t.id)<60).slice(0,4);document.getElementById('sec-estadisticas').innerHTML=sectionHeader('Seguimiento','Estadísticas y progreso','Los datos se guardan localmente en este navegador.')+`<div class="grid-2"><section class="panel"><div class="score-big">${p.pct}%</div><p>Progreso general</p><div class="metric-grid"><div class="metric"><b>${Object.values(state.questionResults).reduce((a,x)=>a+(x.correct||0),0)}</b><span>aciertos teóricos</span></div><div class="metric"><b>${Object.values(state.questionResults).reduce((a,x)=>a+(x.wrong||0),0)}</b><span>fallos teóricos</span></div><div class="metric"><b>${p.eDone}</b><span>ejercicios resueltos</span></div><div class="metric"><b>${p.wDone}</b><span>talleres completos</span></div></div></section><section class="panel"><h2>Recomendación para hoy</h2>${rec.map((t,i)=>`<div class="priority-row"><span class="priority-rank">${i+1}</span><div><b>${esc(t.nombre)}</b><small>Frecuencia ${STATS.frecuencia_por_tema[t.id]||0} · progreso ${topicProgress(t.id)}%</small></div><button class="btn small" data-topic-jump="${t.id}">Empezar</button></div>`).join('')}</section></div><div style="height:20px"></div><div class="grid-2"><section class="panel"><h2>Progreso por tema</h2>${topics.map(t=>`<div class="stat-line"><span>${esc(t.nombre)}</span><div class="bar"><span style="width:${topicProgress(t.id)}%;background:${topicColor[t.id]}"></span></div><b>${topicProgress(t.id)}%</b></div>`).join('')}</section><section class="panel"><h2>Historial de simulacros</h2><div class="timeline">${histories.map(h=>`<div class="timeline-item"><b>${new Date(h.date).toLocaleString('es-UY')}</b><div>${h.correct}/${h.count} correctas · ${h.count?Math.round(100*h.correct/h.count):0}%</div></div>`).join('')||'<p class="muted">Todavía no hay simulacros guardados.</p>'}</div></section></div>`;bindNav()}
function renderSources(){const f=state.filters.sources||{type:'todos'};const types=['todos','nota','practico','taller','parcial','examen'];const list=KB.documentos.filter(d=>f.type==='todos'||d.source_type===f.type);if(!sourceSelected||!list.some(d=>d.id===sourceSelected))sourceSelected=list[0]?.id;const d=docs[sourceSelected];document.getElementById('sec-fuentes').innerHTML=sectionHeader('Trazabilidad','Fuentes','Cada respuesta conserva su documento, año, instancia y enlace original.')+`<div class="source-tabs">${types.map(x=>`<button class="btn source-tab ${f.type===x?'active':''}" data-source-type="${x}">${x==='todos'?'Todas':sourceLabel[x]||x} <span class="badge-count">${x==='todos'?KB.documentos.length:KB.documentos.filter(d=>d.source_type===x).length}</span></button>`).join('')}</div><div class="split"><div class="list-panel">${list.map(x=>`<button class="list-item ${x.id===sourceSelected?'active':''}" data-source-id="${x.id}"><strong>${esc(x.nombre)}</strong><small>${sourceLabel[x.source_type]||x.tipo} · ${x.anio||'s/a'} · ${x.instancia||''}</small></button>`).join('')}</div><article class="detail">${d?`<div class="chips">${chip(sourceLabel[d.source_type]||d.tipo,'dark')}${chip(String(d.anio||'sin año'))}${chip(d.instancia||'sin instancia')}${d.es_fuente_oficial?chip('Fuente oficial','official'):''}</div><h2>${esc(d.nombre)}</h2><p>${(d.temas||[]).map(id=>chip(topicName(id))).join('')}</p><p><a class="btn primary" href="${esc(d.link)}" target="_blank" rel="noopener">Abrir documento original</a></p><h3>Contenido extraído</h3><div class="source-content">${fmt(d.contenido_completo||'Sin texto extraído.')}</div><h3>Documentos relacionados</h3><div class="chips">${(d.documentos_relacionados||[]).slice(0,12).map(id=>chip(docs[id]?.nombre||id)).join('')}</div>`:'<div class="empty">Sin fuente seleccionada.</div>'}</article></div><p class="counter">Base: ${M.cantidad_documentos} documentos · index.md leído (${DATA.index_meta.bytes.toLocaleString('es-UY')} bytes) · enlaces rotos registrados: ${REL.links_rotos?.length||0}</p>`;document.querySelectorAll('[data-source-type]').forEach(b=>b.onclick=()=>{state.filters.sources={type:b.dataset.sourceType};sourceSelected=null;save();renderSources()});document.querySelectorAll('[data-source-id]').forEach(b=>b.onclick=()=>{sourceSelected=b.dataset.sourceId;renderSources()})}
/* === Interfaz simplificada v2 === */
const examExercises = exercises.filter(e => sourceType(e) === 'examen' && !e.dashboard_exclude);
const examTheory = questions.filter(q => sourceType(q) === 'examen');

function restoreSearchFocus(id, value, caret){
  requestAnimationFrame(()=>{
    const el=document.getElementById(id);
    if(!el)return;
    el.focus({preventScroll:true});
    const pos=Math.min(caret ?? value.length, value.length);
    try{el.setSelectionRange(pos,pos)}catch{}
  });
}
function examCountsByTopic(){
  return topics.map((t,orden)=>({
    ...t,
    orden,
    count: examExercises.filter(e=>e.tema===t.id).length
  })).sort((a,b)=>b.count-a.count||a.orden-b.orden);
}
function personalSummary(){
  const histories=[...state.simulations].reverse();
  const solved=examExercises.filter(e=>state.exerciseStatus[e.id]==='resuelto').length;
  const review=examExercises.filter(e=>isExerciseForReview(e.id)).length;
  const skillDone=skills.filter(s=>state.skillStatus[s.id]==='dominada').length;
  const last=histories[0];
  return {histories,solved,review,skillDone,last};
}
function renderExamFrequencyChart(){
  const rows=topics.map((t,orden)=>({...t,orden,count:examExercises.filter(e=>e.tema===t.id).length}));
  const max=Math.max(...rows.map(x=>x.count),1);
  return `<div class="exam-chart">${rows.map(x=>`<button class="chart-row" data-topic-jump="${x.id}" title="Abrir ${esc(x.nombre)}"><span class="chart-label">${esc(x.nombre)}</span><span class="chart-track"><span class="chart-fill" style="width:${x.count?Math.max(3,100*x.count/max):0}%;background:${topicColor[x.id]}"></span></span><b>${x.count}</b></button>`).join('')}</div>`;
}
function renderHome(){
  const p=progress(), s=personalSummary(), pri=examCountsByTopic().map(t=>({...t,progress:topicProgress(t.id)})).sort((a,b)=>(b.count*(1-b.progress/100))-(a.count*(1-a.progress/100))).slice(0,5);
  document.getElementById('sec-inicio').innerHTML=`
    <div class="hero"><div class="hero-main"><div class="eyebrow">Plan personal</div><h1 class="page-title">Tu preparación para el examen.</h1>
      <div class="metric-grid"><div class="metric"><b>${p.pct}%</b><span>progreso general</span></div><div class="metric"><b>${s.solved}</b><span>ejercicios de examen resueltos</span></div><div class="metric"><b>${s.review}</b><span>marcados para repasar</span></div><div class="metric"><b>${s.skillDone}/${skills.length}</b><span>habilidades dominadas</span></div></div>
      <div class="quick-actions"><button class="btn accent" data-section="banco">Practicar examen</button><button class="btn primary" data-section="simulacro">Iniciar simulacro</button><button class="btn" data-section="temas">Explorar temas</button></div>
    </div><aside class="hero-note"><h2>Qué estudiar ahora</h2>${pri.map((t,i)=>`<div class="priority-row"><span class="priority-rank">${i+1}</span><div><b>${esc(t.nombre)}</b><small>${t.count} ejercicios en exámenes · progreso ${t.progress}%</small></div><button class="btn small" data-topic-jump="${t.id}">Abrir</button></div>`).join('')}</aside></div>
    <div class="grid-2 home-grid"><section class="panel chart-panel"><div class="eyebrow">Frecuencia histórica</div><h2>Ejercicios por tema en todos los exámenes</h2>${renderExamFrequencyChart()}</section>
    <section class="panel"><div class="eyebrow">Desempeño</div><h2>Estadísticas personales</h2><div class="metric-grid compact"><div class="metric"><b>${Object.values(state.questionResults).reduce((a,x)=>a+(x.correct||0),0)}</b><span>respuestas correctas</span></div><div class="metric"><b>${Object.values(state.questionResults).reduce((a,x)=>a+(x.wrong||0),0)}</b><span>respuestas incorrectas</span></div></div><h3>Último simulacro</h3>${s.last?`<div class="score-strip"><b>${s.last.count?Math.round(100*s.last.correct/s.last.count):0}%</b><span>${s.last.correct}/${s.last.count} correctas · ${new Date(s.last.date).toLocaleDateString('es-UY')}</span></div>`:'<p class="muted">Todavía no realizaste simulacros.</p>'}<button class="btn" data-section="simulacro">Ver simulacros</button></section></div>
    <div style="height:20px"></div><div class="grid-2"><section class="panel"><div class="eyebrow">Habilidades</div><h2>Estado personal</h2>${skills.map(sk=>`<div class="skill-row"><div><b>${esc(sk.nombre)}</b><small>${esc(topicName(sk.tema))} · aparece ${sk.frecuencia||0} veces</small></div><select class="status-select" data-home-skill="${sk.id}">${['no_iniciada','en_progreso','dominada'].map(v=>`<option value="${v}" ${(state.skillStatus[sk.id]||'no_iniciada')===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></div>`).join('')}</section>
    <section class="panel"><div class="eyebrow">Plan</div><h2>Checklist personal</h2>${checklistItems().slice(0,12).map(x=>`<div class="check-item"><div><b>${esc(x.title)}</b><div class="muted">${esc(x.desc)}</div></div><select data-home-check="${x.id}">${checklistStates.map(v=>`<option value="${v}" ${(state.checklist[x.id]||'no_iniciado')===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></div>`).join('')}</section></div>`;
  document.querySelectorAll('[data-home-skill]').forEach(el=>el.onchange=()=>{state.skillStatus[el.dataset.homeSkill]=el.value;save()});
  document.querySelectorAll('[data-home-check]').forEach(el=>el.onchange=()=>{state.checklist[el.dataset.homeCheck]=el.value;save()});
  bindNav();
}

function bankExamFilters(){return state.filters.bankExam||{search:'',topic:'',year:'',instance:'',status:''}}
function exerciseBankStatus(id){
  if(isExerciseForReview(id))return 'repasar';
  if(state.exerciseStatus[id]==='resuelto')return 'resuelto';
  return 'pendiente';
}
function filteredExamExercises(){
  const f=bankExamFilters(), term=(f.search||'').trim().toLowerCase();
  return examExercises.filter(e=>(!term||(e.enunciado_completo||'').toLowerCase().includes(term)||(e.solucion||'').toLowerCase().includes(term))&&(!f.topic||e.tema===f.topic)&&(!f.year||String(e.anio)===f.year)&&(!f.instance||String(e.instancia||'')===f.instance)&&(!f.status||exerciseBankStatus(e.id)===f.status));
}
function examHint1(e){
  const hs=(e.habilidades||[]).map(id=>skillMap[id]?.nombre).filter(Boolean);
  return `Ubicá primero el núcleo del ejercicio: ${topicName(e.tema)}${e.subtema?' — '+e.subtema:''}. ${hs.length?'La habilidad principal es '+hs.join(', ')+'.':''} Separá claramente datos, representación y resultado pedido.`;
}
function examHint2(e){
  const concepts=(e.conceptos_utilizados||[]).map(id=>KB.conceptos.find(c=>c.id===id)?.nombre).filter(Boolean);
  return `Armá una resolución por etapas: 1) modelar el estado o formato; 2) aplicar ${concepts.join(', ')||'la técnica del tema'}; 3) comprobar rangos, bits, stack o temporización según corresponda; 4) contrastar cada inciso con la letra.`;
}
function renderExamExerciseDetail(e){
  if(!e)return '<div class="empty">No hay ejercicios para estos filtros.</div>';
  const d=docOf(e), status=exerciseBankStatus(e.id);
  return `<div class="chips">${chip(topicName(e.tema),'dark')}${chip(e.subtema||'')}${chip(String(e.anio||'sin año'))}${chip(e.instancia||'sin instancia')}${chip(status)}${chip('Solución oficial','official')}</div>
  <h2>${esc(e.encabezado_fuente||'Ejercicio')}</h2><div class="exercise-text" style="${topicStyle(e.tema)}">${fmt(e.enunciado_completo||e.enunciado)}</div>
  <div class="quick-actions"><button class="btn" data-exam-action="hint1">Pista 1</button><button class="btn" data-exam-action="hint2">Pista 2</button><button class="btn primary" data-exam-action="solution">Ver solución oficial</button><button class="btn good" data-exam-action="solved">Lo resolví</button><button class="btn bad" data-exam-action="review">${isExerciseForReview(e.id)?'Quitar de repaso':'Necesito repasar'}</button><button class="btn" data-exam-action="favorite">${state.favorites.includes(e.id)?'Quitar favorito':'Marcar favorito'}</button></div><div id="examReveal"></div>
  <p class="counter">Fuente: <a href="${esc(e.link||d.link||'#')}" target="_blank" rel="noopener">${esc(d.nombre||'Examen')}</a>${e.link_solucion?` · <a href="${esc(e.link_solucion)}" target="_blank" rel="noopener">abrir solución original</a>`:''}</p>`;
}
function bindExamActions(e){
  document.querySelectorAll('[data-exam-action]').forEach(b=>b.onclick=()=>{
    const box=document.getElementById('examReveal'), a=b.dataset.examAction;
    if(a==='hint1')box.innerHTML=`<div class="hint-box"><b>Pista 1</b><br><br>${fmt(examHint1(e))}</div>`;
    if(a==='hint2')box.innerHTML=`<div class="hint-box"><b>Pista 2</b><br><br>${fmt(examHint2(e))}</div>`;
    if(a==='solution')box.innerHTML=`<div class="solution-box"><b>Solución oficial</b><br><br>${fmt(e.solucion||'La solución está contenida en el documento oficial enlazado.')}</div>`;
    if(a==='solved'){state.exerciseStatus[e.id]='resuelto';(e.habilidades||[]).forEach(id=>state.skillStatus[id]='en_progreso');save();toast('Ejercicio marcado como resuelto');renderBank()}
    if(a==='review'){const add=!isExerciseForReview(e.id);setExerciseForReview(e.id,add);save();toast(add?'Ejercicio marcado para repasar':'Ejercicio quitado de repaso');renderBank()}
    if(a==='favorite'){state.favorites=state.favorites.includes(e.id)?state.favorites.filter(x=>x!==e.id):[...state.favorites,e.id];save();renderBank()}
  });
}
function renderBank(opts={}){
  const f=bankExamFilters(), list=filteredExamExercises();
  if(!bankSelected||!list.some(e=>e.id===bankSelected))bankSelected=list[0]?.id;
  const e=examExercises.find(x=>x.id===bankSelected), years=uniq(examExercises.map(x=>String(x.anio||''))).filter(Boolean).sort().reverse(), instances=uniq(examExercises.map(x=>x.instancia).filter(Boolean)).sort();
  document.getElementById('sec-banco').innerHTML=sectionHeader('','Banco de ejercicios de examen','')+`
  <div class="filters exam-bank-filters"><div class="field search-wide"><label>Buscar en letra o solución</label><input id="xbfSearch" value="${esc(f.search||'')}" placeholder="Escribí sin perder el foco…"></div><div class="field"><label>Tema</label><select id="xbfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div><div class="field"><label>Año</label><select id="xbfYear">${optionList(years,f.year)}</select></div><div class="field"><label>Instancia</label><select id="xbfInstance">${optionList(instances,f.instance)}</select></div><div class="field"><label>Estado</label><select id="xbfStatus">${optionList([{value:'pendiente',label:'Pendiente'},{value:'resuelto',label:'Resuelto'},{value:'repasar',label:'Repasar'}],f.status)}</select></div></div>
  <div class="split"><div class="list-panel">${list.map(x=>`<button class="list-item ${x.id===bankSelected?'active':''}" data-exam-id="${x.id}"><strong>${esc(x.encabezado_fuente||'Ejercicio')}</strong><small>${x.anio||'s/a'} · ${x.instancia||''} · ${esc(topicName(x.tema))}</small><span class="list-preview">${esc((x.enunciado_completo||'').replace(/\s+/g,' ').slice(0,150))}</span></button>`).join('')||'<div class="empty">No hay coincidencias.</div>'}</div><article class="detail">${renderExamExerciseDetail(e)}</article></div><p class="counter">${list.length} de ${examExercises.length} ejercicios de examen</p>`;
  const input=document.getElementById('xbfSearch');
  input.oninput=()=>{const caret=input.selectionStart;state.filters.bankExam={...bankExamFilters(),search:input.value};save();renderBank({focus:true,caret})};
  ['xbfTopic','xbfYear','xbfInstance','xbfStatus'].forEach(id=>document.getElementById(id).onchange=()=>{state.filters.bankExam={search:document.getElementById('xbfSearch').value,topic:document.getElementById('xbfTopic').value,year:document.getElementById('xbfYear').value,instance:document.getElementById('xbfInstance').value,status:document.getElementById('xbfStatus').value};bankSelected=null;save();renderBank()});
  document.querySelectorAll('[data-exam-id]').forEach(b=>b.onclick=()=>{bankSelected=b.dataset.examId;renderBank()});
  if(e)bindExamActions(e);
  if(opts.focus)restoreSearchFocus('xbfSearch',f.search||'',opts.caret);
}

function renderSimulation(){
  if(sim?.active)return renderSimQuestion();if(sim?.finished)return renderSimResult();
  const f=simFilters();
  document.getElementById('sec-simulacro').innerHTML=sectionHeader('','Simulacro y teoría rápida','')+`<section class="panel sim-card"><div class="grid-2"><div class="field"><label>Cantidad</label><select id="sfCount">${[5,10,15,20].map(n=>`<option ${n==f.count?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Modo</label><select id="sfMode"><option value="teoria" ${f.mode==='teoria'?'selected':''}>Teoría rápida de exámenes</option><option value="practica" ${f.mode==='practica'?'selected':''}>Ejercicios de examen</option><option value="mixto" ${f.mode==='mixto'?'selected':''}>Mixto</option></select></div><div class="field"><label>Tema</label><select id="sfTopic">${optionList(topics.map(t=>({value:t.id,label:t.nombre})),f.topic)}</select></div></div><label class="checkline"><input id="sfFreq" type="checkbox" ${f.frequent?'checked':''}>Priorizar temas frecuentes</label><label class="checkline"><input id="sfWeak" type="checkbox" ${f.weak?'checked':''}>Priorizar habilidades débiles</label><div class="quick-actions"><button class="btn accent" id="startSim">Comenzar</button><button class="btn" data-section="banco">Ir al banco de ejercicios</button></div><p class="counter">Disponible: ${examTheory.length} preguntas teóricas y ${examExercises.length} ejercicios de examen.</p></section>`;
  document.getElementById('startSim').onclick=()=>{const count=+$id('sfCount').value,mode=$id('sfMode').value,topic=$id('sfTopic').value;let pool=[];if(mode!=='practica')pool.push(...examTheory.filter(q=>!topic||q.tema===topic).map(q=>({kind:'q',id:q.id,topic:q.tema})));if(mode!=='teoria')pool.push(...examExercises.filter(e=>!topic||e.tema===topic).map(e=>({kind:'e',id:e.id,topic:e.tema})));pool.sort(()=>Math.random()-.5);sim={active:true,finished:false,index:0,items:pool.slice(0,count),answers:[],revealed:false,reviewSaved:false};renderSimulation()};bindNav();
}

function renderTopics(){
  const selected=state.lastTopic||examCountsByTopic()[0]?.id||topics[0]?.id,t=topicMap[selected];if(!t)return;
  const sub=KB.subtemas.filter(s=>s.tema===t.id),sk=skills.filter(s=>s.tema===t.id),examEs=examExercises.filter(e=>e.tema===t.id),sourceDocs=KB.documentos.filter(d=>(d.temas||[]).includes(t.id));
  const list=topics.map(x=>{const n=examExercises.filter(e=>e.tema===x.id).length;return `<button class="topic-card ${x.id===selected?'active':''}" style="${topicStyle(x.id)}" data-topic-jump="${x.id}"><strong>${esc(x.nombre)}</strong><small>${n} ejercicios · progreso ${topicProgress(x.id)}%</small><div class="bar" style="margin-top:12px"><span style="width:${topicProgress(x.id)}%"></span></div></button>`}).join('');
  const top=examCountsByTopic()[0];
  document.getElementById('sec-temas').innerHTML=sectionHeader('','Vista general','')+`<div class="course-overview"><section class="panel chart-panel"><div class="eyebrow">Frecuencia histórica</div><h2>Ejercicios por tema</h2>${renderExamFrequencyChart()}</section><section class="panel course-metrics"><div class="metric"><b>${examExercises.length}</b><span>ejercicios únicos</span></div><div class="metric"><b>${examGroups().length}</b><span>exámenes analizados</span></div><div class="metric"><b>${top?.count||0}</b><span>máximo en un tema</span></div><div class="metric"><b>${topics.filter(x=>examExercises.some(e=>e.tema===x.id)).length}/16</b><span>temas presentes</span></div><h3>${esc(top?.nombre||'')}</h3><p class="muted">Tema más frecuente</p></section></div><div class="topic-strip">${list}</div><div style="height:18px"></div><div class="topic-detail-head" style="${topicStyle(t.id)}"><small>${examEs.length} ejercicios · progreso ${topicProgress(t.id)}%</small><h2>${esc(t.nombre)}</h2><div class="quick-actions"><button class="btn accent" id="topicExamBank">Practicar</button><button class="btn" id="topicSim">Mini simulacro</button><button class="btn" id="topicSources">Fuentes</button></div></div><div class="topic-columns"><section class="panel"><h3>Subtemas</h3><div class="chips">${sub.map(x=>chip(x.nombre)).join('')}</div><h3>Habilidades</h3>${sk.map(x=>`<div class="mini-row" style="${topicStyle(t.id)}"><b>${esc(x.nombre)}</b></div>`).join('')||'<p class="muted">Sin habilidades clasificadas.</p>'}</section><section class="panel"><h3>Ejercicios de examen</h3>${examEs.slice(0,10).map(e=>`<button class="list-item" data-topic-exam="${e.id}"><strong>${esc(e.encabezado_fuente||'Ejercicio')}</strong><small>${e.anio||'s/a'} · ${e.instancia||''}</small><span class="list-preview">${esc((e.enunciado_completo||'').replace(/\s+/g,' ').slice(0,130))}</span></button>`).join('')||'<p class="muted">Sin ejercicios.</p>'}</section><section class="panel"><h3>Fuentes asociadas</h3><p><b>${sourceDocs.length}</b> documentos</p>${sourceDocs.slice(0,10).map(d=>`<div class="mini-row" style="${topicStyle(t.id)}"><a href="${esc(d.link)}" target="_blank" rel="noopener"><b>${esc(d.nombre)}</b></a><div class="muted">${esc(sourceLabel[d.source_type]||d.tipo)}</div></div>`).join('')}</section><section class="panel"><h3>Progreso</h3><div class="score-big">${topicProgress(t.id)}%</div><div class="bar"><span style="width:${topicProgress(t.id)}%;background:${topicColor[t.id]}"></span></div></section></div>`;
  bindNav();
  document.getElementById('topicExamBank').onclick=()=>{state.filters.bankExam={...bankExamFilters(),topic:t.id};bankSelected=null;save();navTo('banco')};
  document.getElementById('topicSim').onclick=()=>{state.filters.sim={...simFilters(),topic:t.id,count:5,mode:'mixto'};save();navTo('simulacro')};
  document.getElementById('topicSources').onclick=()=>{state.filters.sources={type:'todos'};save();navTo('fuentes')};
  document.querySelectorAll('[data-topic-exam]').forEach(b=>b.onclick=()=>{bankSelected=b.dataset.topicExam;state.filters.bankExam={...bankExamFilters(),topic:t.id};save();navTo('banco')});
}


let examOverviewSelected=null;
function interruptionRelated(e){
  const text=((e.enunciado_completo||'')+' '+(e.subtema||'')+' '+topicName(e.tema)).toLowerCase();
  return e.tema==='tema_13_io_interrupciones'||/interrup|rutina de atenci|puerto de e\/s|timer|controlador de interrupciones|vector de interrupciones/.test(text);
}
function examGroups(){
  const map={};
  examExercises.forEach(e=>{
    const d=docOf(e), key=e.documento||`${e.anio}-${e.instancia||''}`;
    if(!map[key])map[key]={id:key,doc:d,anio:e.anio||d.anio,instancia:e.instancia||d.instancia||'',nombre:d.nombre||'Examen',items:[]};
    map[key].items.push(e);
  });
  return Object.values(map).sort((a,b)=>(b.anio||0)-(a.anio||0)||String(b.instancia).localeCompare(String(a.instancia)));
}
function countsForExam(g){
  const c={};g.items.forEach(e=>c[e.tema]=(c[e.tema]||0)+1);return c;
}
function relatedTopicsForExam(g){
  const ids=new Set();
  g.items.forEach(e=>{ids.add(e.tema);const d=docOf(e);(d.temas||[]).forEach(x=>ids.add(x));});
  if(g.items.some(interruptionRelated))ids.add('tema_13_io_interrupciones');
  return [...ids];
}
function recentTrendRows(){
  const historical={};examExercises.forEach(e=>historical[e.tema]=(historical[e.tema]||0)+1);
  const recentItems=examExercises.filter(e=>(e.anio||0)>=2022);
  const recent={};recentItems.forEach(e=>recent[e.tema]=(recent[e.tema]||0)+1);
  const totalH=examExercises.length||1,totalR=recentItems.length||1;
  return topics.map(t=>{
    const hp=(historical[t.id]||0)/totalH, rp=(recent[t.id]||0)/totalR;
    return {id:t.id,name:t.nombre,h:historical[t.id]||0,r:recent[t.id]||0,hp,rp,delta:rp-hp};
  }).filter(x=>x.h||x.r).sort((a,b)=>b.delta-a.delta);
}
function renderExamsOverview(){
  const groups=examGroups();
  if(!examOverviewSelected||!groups.some(g=>g.id===examOverviewSelected))examOverviewSelected=groups[0]?.id;
  const g=groups.find(x=>x.id===examOverviewSelected)||groups[0];
  const counts=g?countsForExam(g):{}, max=Math.max(1,...Object.values(counts));
  const rows=recentTrendRows();
  document.getElementById('sec-examenes').innerHTML=sectionHeader('','Temas por examen','')+`
  <div class="exam-overview-grid">
    <div class="exam-list">${groups.map(x=>`<button class="${x.id===examOverviewSelected?'active':''}" data-exam-overview="${x.id}"><b>${x.anio||'s/a'} · ${esc(x.instancia||'sin instancia')}</b><small>${esc(x.nombre)} · ${x.items.length} ejercicios</small></button>`).join('')}</div>
    <article class="panel">${g?`<div class="eyebrow">Examen seleccionado</div><h2>${g.anio||'s/a'} · ${esc(g.instancia||'sin instancia')}</h2>
      <p><a class="btn" href="${esc(g.doc.link||'#')}" target="_blank" rel="noopener">Abrir examen original</a></p>
      <h3>Temas del examen</h3>
      ${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([id,n])=>`<div class="exam-topic-row"><span>${esc(topicName(id))}</span><div class="exam-topic-track"><span style="width:${100*n/max}%;background:${topicColor[id]||'#657180'}"></span></div><b>${n}</b></div>`).join('')}
      <h3>Ejercicios</h3>${g.items.map(e=>`<button class="list-item" data-overview-open="${e.id}"><strong>${esc(e.encabezado_fuente||'Ejercicio')}</strong><small>${esc(topicName(e.tema))} · ${esc(e.subtema||'')}</small></button>`).join('')}`:'<p>Sin examen seleccionado.</p>'}</article>
  </div>
  <div style="height:22px"></div>
  <section class="panel"><h2>Histórico y 2022–2026</h2>
  <div style="overflow:auto"><table class="trend-table"><thead><tr><th>Tema</th><th>Histórico</th><th>2022–2026</th><th>Cambio</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.h} (${Math.round(x.hp*100)}%)</td><td>${x.r} (${Math.round(x.rp*100)}%)</td><td class="${x.delta>0?'trend-up':'trend-down'}">${x.delta>0?'+':''}${Math.round(x.delta*100)} pp</td></tr>`).join('')}</tbody></table></div></section>`;
  document.querySelectorAll('[data-exam-overview]').forEach(b=>b.onclick=()=>{examOverviewSelected=b.dataset.examOverview;renderExamsOverview()});
  document.querySelectorAll('[data-overview-open]').forEach(b=>b.onclick=()=>{bankSelected=b.dataset.overviewOpen;state.filters.bankExam={search:'',topic:'',year:'',instance:'',status:''};save();navTo('banco')});
}

