defaultState.topicResolutionChecklist=defaultState.topicResolutionChecklist||{};
defaultState.exerciseNotes=defaultState.exerciseNotes||{};
defaultState.examNotes=defaultState.examNotes||{};
defaultState.lastExamOverview=defaultState.lastExamOverview||null;

