function setupPersistence(){document.getElementById('exportProgress').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='progreso_arquitectura.json';a.click();URL.revokeObjectURL(a.href)};document.getElementById('importProgress').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state={...structuredClone(defaultState),...JSON.parse(r.result)};save();toast('Progreso importado');navTo(state.lastSection||'inicio')}catch{toast('Archivo inválido')}};r.readAsText(f)};document.getElementById('resetProgress').onclick=()=>{if(confirm('¿Reiniciar todo el progreso guardado?')){state=structuredClone(defaultState);save();toast('Progreso reiniciado');navTo('inicio')}}}
document.getElementById('menuToggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('sidebar').classList.remove('open')});
