/* =========================================================
   V11 · plan adaptativo por fecha exacta y carga equilibrada
   ========================================================= */
const PLAN_RECENT_A_START_V11=2024;
const PLAN_RECENT_A_END_V11=2026;
const PLAN_RECENT_B_START_V11=2022;
const PLAN_RECENT_B_END_V11=2023;
const PLAN_HISTORICAL_CORRECTION_RATE_V11=.25;
const PLAN_HISTORICAL_CORRECTION_CAP_V11=3;

function planFrequencyStatsV11(){
 const counts2426={},counts2223={},countsHistorical={},countsTotal={};
 examExercises.forEach(e=>{
  const year=Number(e.anio)||0,topic=e.tema;
  if(!topic)return;
  countsTotal[topic]=(countsTotal[topic]||0)+1;
  if(year>=PLAN_RECENT_A_START_V11&&year<=PLAN_RECENT_A_END_V11)counts2426[topic]=(counts2426[topic]||0)+1;
  else if(year>=PLAN_RECENT_B_START_V11&&year<=PLAN_RECENT_B_END_V11)counts2223[topic]=(counts2223[topic]||0)+1;
  else if(year&&year<PLAN_RECENT_B_START_V11)countsHistorical[topic]=(countsHistorical[topic]||0)+1;
 });
 const rawByTopic={};
 topics.forEach(t=>{
  const recent=counts2426[t.id]||0,additional=counts2223[t.id]||0,historical=countsHistorical[t.id]||0;
  const historicalCorrection=Math.min(PLAN_HISTORICAL_CORRECTION_CAP_V11,historical*PLAN_HISTORICAL_CORRECTION_RATE_V11);
  rawByTopic[t.id]=4*recent+1.5*additional+historicalCorrection;
 });
 const rawValues=Object.values(rawByTopic),maxRaw=Math.max(1,...rawValues),positive=rawValues.filter(x=>x>0),averageRaw=positive.length?positive.reduce((a,n)=>a+n,0)/positive.length:1;
 return {counts2426,counts2223,countsHistorical,countsTotal,rawByTopic,maxRaw,averageRaw};
}
function planTopicPriorityV11(topic,stats=planFrequencyStatsV11()){
 if(!topic){
  const raw=Math.max(5,stats.averageRaw*.85);
  return {raw,factor:raw/Math.max(1,stats.averageRaw),recent:0,additional:0,historical:0,historicalCorrection:0,label:'Integración',level:'integral'};
 }
 const recent=stats.counts2426[topic]||0,additional=stats.counts2223[topic]||0,historical=stats.countsHistorical[topic]||0;
 const historicalCorrection=Math.min(PLAN_HISTORICAL_CORRECTION_CAP_V11,historical*PLAN_HISTORICAL_CORRECTION_RATE_V11);
 const raw=4*recent+1.5*additional+historicalCorrection;
 const factor=Math.max(.12,raw/Math.max(1,stats.averageRaw));
 const relative=raw/stats.maxRaw;
 const level=relative>=.67?'alta':relative>=.30?'media':'baja';
 const label=level==='alta'?'Prioridad alta':level==='media'?'Prioridad media':'Prioridad base';
 return {raw,factor,recent,additional,historical,historicalCorrection,label,level};
}
function planKindFactorV11(kind){return ({repaso:.76,procedimiento:1,ejercicio:1.10,desafio:1.20,practica:1.08,simulacro:1.30})[kind]||1}
function planModuleEffortV11(m,stats=planFrequencyStatsV11()){
 const priority=planTopicPriorityV11(m.topic,stats),progress=Math.max(0,Math.min(1,planModuleProgressV7(m))),remaining=Math.max(0,1-progress);
 const base=m.weight*planKindFactorV11(m.kind);
 const priorityMultiplier=1+priority.raw/Math.max(1,stats.averageRaw);
 return Math.max(.08,base*priorityMultiplier*remaining);
}
function planModuleScoreV11(m,stats=planFrequencyStatsV11()){
 const priority=planTopicPriorityV11(m.topic,stats),remaining=Math.max(0,1-Math.max(0,Math.min(1,planModuleProgressV7(m))));
 return priority.raw*remaining;
}
function planPartitionCostV11(items,efforts,start,end,targetLoad,targetCount){
 let load=0,simulations=0;const topicsInGroup=new Set();let minPhase=Infinity,maxPhase=-Infinity;
 for(let i=start;i<end;i++){
  const m=items[i];load+=efforts[i];if(m.kind==='simulacro')simulations++;if(m.topic)topicsInGroup.add(m.topic);minPhase=Math.min(minPhase,m.phase);maxPhase=Math.max(maxPhase,m.phase);
 }
 const count=end-start;
 const loadError=Math.pow((load-targetLoad)/Math.max(.1,targetLoad),2);
 const countError=Math.pow((count-targetCount)/Math.max(1,targetCount),2);
 const mixedSimulationPenalty=simulations&&count>simulations?.55*(count-simulations):0;
 const multipleSimulationPenalty=simulations>1?3*(simulations-1):0;
 const topicPenalty=Math.max(0,topicsInGroup.size-3)*.12;
 const phaseSpan=Math.max(0,maxPhase-minPhase);
 const phasePenalty=phaseSpan>1?.06*Math.pow(phaseSpan-1,2):0;
 return loadError+2.15*countError+mixedSimulationPenalty+multipleSimulationPenalty+topicPenalty+phasePenalty;
}
function partitionPlanModulesV11(items,efforts,groupCount){
 const n=items.length,k=Math.max(0,Math.min(groupCount,n));
 if(!k)return [];
 const total=efforts.reduce((a,n)=>a+n,0),targetLoad=total/k,targetCount=n/k,INF=Number.POSITIVE_INFINITY;
 const dp=Array.from({length:k+1},()=>Array(n+1).fill(INF));
 const prev=Array.from({length:k+1},()=>Array(n+1).fill(-1));
 dp[0][0]=0;
 for(let g=1;g<=k;g++){
  for(let j=g;j<=n;j++){
   for(let i=g-1;i<j;i++){
    if(!Number.isFinite(dp[g-1][i]))continue;
    const cost=dp[g-1][i]+planPartitionCostV11(items,efforts,i,j,targetLoad,targetCount);
    if(cost<dp[g][j]){dp[g][j]=cost;prev[g][j]=i}
   }
  }
 }
 const groups=[];let g=k,j=n;
 while(g>0){const i=prev[g][j];groups.unshift(items.slice(i,j));j=i;g--}
 return groups;
}
function spreadGroupsAcrossDatesV11(groups,dates){
 const buckets=dates.map(date=>({date,tasks:[],load:0}));
 if(!groups.length||!buckets.length)return buckets;
 if(groups.length===1){
  const only=groups[0],late=only.some(m=>m.kind==='simulacro'||m.phase>=8),idx=late?buckets.length-1:0;
  buckets[idx].tasks=only;return buckets;
 }
 groups.forEach((group,i)=>{
  const idx=Math.round(i*(buckets.length-1)/(groups.length-1));
  buckets[idx].tasks=group;
 });
 return buckets;
}
function planScheduleV11(){
 ensureWorkspaceV7();
 const configured=v7Date(state.studyPlan.startDate),exam=v7Date(state.studyPlan.examDate),effective=configured;
 const dates=[];
 if(configured<exam){for(let d=new Date(configured);d<exam;d=v7AddDays(d,1))dates.push(new Date(d))}
 const stats=planFrequencyStatsV11();
 const pending=STUDY_PLAN_MODULES.filter(m=>!planModuleDoneV7(m));
 const completed=STUDY_PLAN_MODULES.filter(planModuleDoneV7);
 if(!dates.length)return {configured,effective,exam,days:[],pending,completed,stats,topicDays:{},topicLoads:{},targetLoad:0,balanceDeviation:0};
 const ordered=[...pending].sort((a,b)=>a.phase-b.phase||planModuleScoreV11(b,stats)-planModuleScoreV11(a,stats)||a.title.localeCompare(b.title,'es'));
 const efforts=ordered.map(m=>planModuleEffortV11(m,stats));
 const groupCount=Math.min(dates.length,Math.max(1,ordered.length));
 const groups=partitionPlanModulesV11(ordered,efforts,groupCount);
 const buckets=spreadGroupsAcrossDatesV11(groups,dates);
 const effortById=Object.fromEntries(ordered.map((m,i)=>[m.id,efforts[i]]));
 buckets.forEach(day=>{day.load=day.tasks.reduce((sum,m)=>sum+(effortById[m.id]||0),0)});
 const nonEmpty=buckets.filter(d=>d.tasks.length),totalLoad=nonEmpty.reduce((a,d)=>a+d.load,0),targetLoad=nonEmpty.length?totalLoad/nonEmpty.length:0;
 const balanceDeviation=nonEmpty.length&&targetLoad?Math.sqrt(nonEmpty.reduce((a,d)=>a+Math.pow((d.load-targetLoad)/targetLoad,2),0)/nonEmpty.length):0;
 const topicDays={},topicLoads={};
 buckets.forEach(day=>{
  const seen=new Set();
  day.tasks.forEach(m=>{if(!m.topic)return;topicLoads[m.topic]=(topicLoads[m.topic]||0)+(effortById[m.id]||0);seen.add(m.topic)});
  seen.forEach(topic=>topicDays[topic]=(topicDays[topic]||0)+1);
 });
 return {configured,effective,exam,days:buckets,pending,completed,stats,topicDays,topicLoads,targetLoad,balanceDeviation};
}
planScheduleV7=planScheduleV11;

function planPriorityBadgeV11(m,stats){
 if(!m.topic)return '<span class="plan-priority-badge integral">Práctica integral</span>';
 const p=planTopicPriorityV11(m.topic,stats),remaining=Math.round(100*Math.max(0,1-planModuleProgressV7(m)));
 return `<span class="plan-priority-badge ${p.level}">${p.label} · índice ${p.raw.toFixed(1)} · ${remaining}% pendiente</span>`;
}
function planFrequencyPanelV11(p){
 const rows=topics.map(t=>{
  const pr=planTopicPriorityV11(t.id,p.stats),days=p.topicDays[t.id]||0,load=p.topicLoads[t.id]||0;
  return {topic:t,pr,days,load};
 }).filter(x=>x.pr.raw>0||x.days>0).sort((a,b)=>b.pr.raw-a.pr.raw||b.load-a.load);
 const max=Math.max(1,...rows.map(x=>x.pr.raw));
 return `<section class="panel plan-frequency-panel"><div class="plan-frequency-head"><div><div class="eyebrow">Tiempo asignado por frecuencia reciente</div><h2>Prioridad ponderada de los temas</h2><small>Prioridad = 4× apariciones 2024–2026 + 1,5× apariciones 2022–2023 + corrección histórica (0,25× anteriores, máximo 3), multiplicada por lo que falta dominar.</small></div><span>${examExercises.length} ejercicios únicos</span></div><div class="plan-frequency-grid">${rows.map(x=>`<div class="plan-frequency-row" style="--topic:${topicColor[x.topic.id]}"><div><strong>${esc(x.topic.nombre)}</strong><small>${x.pr.recent} recientes · ${x.pr.additional} en 2022–2023 · ${x.pr.historical} históricos · ${x.days} día${x.days===1?'':'s'}</small></div><div class="plan-frequency-track"><i style="width:${Math.round(100*x.pr.raw/max)}%"></i></div><b>${x.pr.raw.toFixed(1)}</b></div>`).join('')}</div></section>`;
}
function bindPlanDatesV11(){
 const start=document.getElementById('planStartDate'),exam=document.getElementById('planExamDate');
 if(start)start.onchange=e=>{state.studyPlan.startDate=e.target.value;save();renderPlan();toast('Plan regenerado desde la fecha elegida')};
 if(exam)exam.onchange=e=>{state.studyPlan.examDate=e.target.value;save();renderPlan();toast('Plan regenerado hasta la nueva fecha de examen')};
}
renderPlan=function(){
 ensureWorkspaceV7();ensurePlanRoadmapSyncV8();const p=planScheduleV7(),total=STUDY_PLAN_MODULES.length,done=p.completed.length,pct=Math.round(100*done/total),nonEmpty=p.days.filter(d=>d.tasks.length),avg=nonEmpty.length?(p.pending.length/nonEmpty.length).toFixed(1):0;
 const maxLoad=Math.max(1,...p.days.map(d=>d.load));
 const balanceLabel=p.balanceDeviation<=.16?'Muy pareja':p.balanceDeviation<=.30?'Equilibrada':'Ajustada por prerrequisitos';
 document.getElementById('sec-plan').innerHTML=`<div class="plan-shell">${sectionHeader('Plan personal','Plan diario','')}
 <div class="plan-sync-banner"><span>↔</span><div><strong>Plan adaptativo y roadmap sincronizados</strong><small>La fecha inicial elegida se respeta exactamente. Al cambiar fechas o progreso, se redistribuye únicamente lo pendiente.</small></div></div>
 <div class="plan-setup"><section class="panel"><div class="plan-controls"><div class="field"><label>Inicio del plan</label><input id="planStartDate" type="date" value="${state.studyPlan.startDate}"></div><div class="field"><label>Fecha de examen</label><input id="planExamDate" type="date" value="${state.studyPlan.examDate}"></div><button class="btn primary" id="rebuildPlan">Reorganizar</button></div><div class="plan-summary"><div class="metric"><b>${p.days.length}</b><span>días disponibles</span></div><div class="metric"><b>${p.pending.length}</b><span>bloques pendientes</span></div><div class="metric"><b>${done}</b><span>bloques completados</span></div><div class="metric"><b>${avg}</b><span>bloques por día activo</span></div><div class="metric"><b>${balanceLabel}</b><span>distribución</span></div></div><div class="bar" style="margin-top:14px"><span style="width:${pct}%"></span></div></section>
 <section class="panel"><div class="eyebrow">Objetivos</div><h2>Objetivos de esta preparación</h2><div class="plan-objectives">${state.personalPanel.objectives.map(o=>`<input class="plan-objective" data-plan-objective="${o.id}" value="${esc(o.text)}">`).join('')}</div></section></div>
 ${planFrequencyPanelV11(p)}
 ${p.days.length?`<div class="plan-days">${p.days.map((day,i)=>{const iso=v7Iso(day.date),isToday=iso===v7Iso(v7Today()),past=day.date<v7Today(),loadPct=p.targetLoad?Math.min(100,Math.round(100*day.load/Math.max(p.targetLoad,maxLoad*.75))):0;return `<article class="plan-day ${isToday?'today':''} ${past?'past':''}" style="--day:${palette[i%palette.length]}"><div class="plan-day-head"><div><div class="eyebrow">Día ${i+1}</div><h3>${esc(v7DateLabel(day.date))}</h3></div><span class="plan-day-badge">${day.tasks.length} bloque${day.tasks.length===1?'':'s'} · ${day.load.toFixed(1)} carga</span></div><div class="plan-load"><span style="width:${loadPct}%"></span></div>${day.tasks.map(m=>{const mp=Math.round(planModuleProgressV7(m)*100);return `<label class="plan-task"><input type="checkbox" data-plan-complete="${m.id}"><span class="plan-task-main"><strong>${esc(m.title)}</strong><small>${m.topic?esc(topicName(m.topic)):'Práctica integral'} · ${esc(m.kind)}${m.nodes.length?` · ${m.nodes.length} pasos`:''}</small>${planPriorityBadgeV11(m,p.stats)}${m.nodes.length?`<span class="plan-roadmap-progress"><i style="width:${mp}%"></i></span><small class="plan-roadmap-caption">${mp}% reflejado en el roadmap</small>`:''}<span class="plan-task-actions">${planTaskActionV8(m)}</span></span></label>`}).join('')||'<div class="plan-empty">Día libre, recuperación o descanso.</div>'}</article>`}).join('')}</div>`:`<div class="plan-empty">La fecha de examen debe ser posterior al inicio del plan.</div>`}
 ${p.completed.length?`<section class="panel"><div class="eyebrow">Completado</div><h2>Bloques ya cubiertos</h2><div class="plan-completed">${p.completed.map(m=>`<span class="plan-completed-item"><button data-plan-undo="${m.id}" title="Volver a incluir en el plan">✓ ${esc(m.title)}</button>${m.nodes.length?`<button class="plan-completed-roadmap" data-plan-roadmap="${m.id}" title="Ver en roadmap">↗</button>`:''}</span>`).join('')}</div></section>`:''}</div>`;
 bindPlanDatesV11();
 document.getElementById('rebuildPlan').onclick=()=>{save();renderPlan();toast('Plan redistribuido desde la fecha seleccionada')};
 document.querySelectorAll('[data-plan-objective]').forEach(el=>el.oninput=()=>{const o=state.personalPanel.objectives.find(x=>x.id===el.dataset.planObjective);if(o)o.text=el.value;save()});
 document.querySelectorAll('[data-plan-complete]').forEach(el=>el.onchange=()=>{const m=moduleByIdV8(el.dataset.planComplete);setPlanModuleDoneV8(m,true);toast('Bloque completado; el resto se redistribuyó');renderPlan()});
 document.querySelectorAll('[data-plan-undo]').forEach(b=>b.onclick=()=>{const m=moduleByIdV8(b.dataset.planUndo);setPlanModuleDoneV8(m,false);toast('Bloque reabierto; el plan fue recalculado');renderPlan()});
 document.querySelectorAll('[data-plan-roadmap]').forEach(b=>b.onclick=e=>{e.preventDefault();const m=moduleByIdV8(b.dataset.planRoadmap);focusRoadmapNodeV8(moduleRoadmapTargetV8(m))});
 document.querySelectorAll('[data-plan-topic]').forEach(b=>b.onclick=e=>{e.preventDefault();state.lastTopic=b.dataset.planTopic;save();navTo('temas',{topic:b.dataset.planTopic})});
 document.querySelectorAll('[data-plan-practice]').forEach(b=>b.onclick=e=>{e.preventDefault();state.filters.bankExam={search:'',topic:b.dataset.planPractice,year:'',instance:'',status:''};bankSelected=null;save();navTo('banco')});
 document.querySelectorAll('[data-plan-mixed]').forEach(b=>b.onclick=e=>{e.preventDefault();state.filters.bankExam={search:'',topic:'',year:'',instance:'',status:'repasar'};bankSelected=null;save();navTo('banco')});
 document.querySelectorAll('[data-plan-sim]').forEach(b=>b.onclick=e=>{e.preventDefault();navTo('simulacro')});
};

