 document.getElementById('sec-fuentes').innerHTML=sectionHeader('Trazabilidad','Fuentes','Buscá por nombre, año, tema, subtema o contenido extraído.')+`<div class="source-searchbar"><div class="field search-wide"><label>Buscar fuentes</label><input id="sourceSearchV12" value="${esc(f.search)}" placeholder="Ej.: interrupciones, 2025, ROM, práctico 4…"></div><span id="sourceCountV12" class="counter"></span></div><div class="source-tabs">${types.map(x=>`<button class="btn source-tab ${f.type===x?'active':''}" data-source-type="${x}">${x==='todos'?'Todas':sourceLabel[x]||x} <span class="badge-count">${x==='todos'?KB.documentos.length:KB.documentos.filter(d=>d.source_type===x).length}</span></button>`).join('')}</div><div class="split source-split-v12"><div class="list-panel" id="sourceListV12"></div><article class="detail" id="sourceDetailV12"></article></div><p class="counter">Base: ${M.cantidad_documentos} documentos · index.md leído (${DATA.index_meta.bytes.toLocaleString('es-UY')} bytes) · enlaces rotos registrados: ${REL.links_rotos?.length||0}</p>`;
 const input=document.getElementById('sourceSearchV12');
 input.oninput=()=>{state.filters.sources={...sourceFiltersV12(),search:input.value};save();renderSourceResultsV12()};
 document.querySelectorAll('[data-source-type]').forEach(b=>b.onclick=()=>{state.filters.sources={...sourceFiltersV12(),type:b.dataset.sourceType};sourceSelected=null;save();renderSources()});
 renderSourceResultsV12();
