 const selectorRows=topics.map(x=>{const n=examExercises.filter(e=>e.tema===x.id).length,cs=topicChecklistStatsV6(x.id);return `<button class="topic-selector-row ${x.id===selected?'active':''}" style="--topic:${topicColor[x.id]}" data-topic-select="${x.id}"><span><strong>${esc(x.nombre)}</strong><small>${n} ejercicios · ${topicProgress(x.id)}% dominado</small></span><b>${cs.done}/${cs.total}</b></button>`}).join('');
